async function runSyncCycle(manual=false){if(manual&&Date.now()<manualSyncLockedUntil){toast('Please wait a few seconds before syncing again.');return;}if(syncBusy||document.hidden||syncClient.metadata()?.pendingReview||!syncClient.metadata()?.credential)return;if(manual)manualSyncLockedUntil=Date.now()+5000;syncBusy=true;syncStatus='syncing';updateSyncStatus();const submitted=JSON.parse(JSON.stringify(state));try{const result=await syncClient.sync(submitted);if(JSON.stringify(state)!==JSON.stringify(submitted)){queueCloudSync();return;}if(result.changed){persistSyncedState(result.data);syncStatus='synced';if(['profile','history','home'].includes(route()[0]))render();if(manual)toast('Your study data is synced across linked devices.');}else syncStatus='synced';}catch(error){if(error.status===401){clearRevokedDevice();return;}syncStatus='offline';if(manual)toast('Sync is unavailable. Your study data remains saved on this device.');}finally{syncBusy=false;updateSyncStatus();}}
