function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${customIcons[n]||icons[n]||icons.book}</svg>`;}
function btn(text,action,cls='',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function link(text,path,cls='',attrs=''){return `<a class="${cls}" href="#${path}" ${attrs}>${text}</a>`;}
function go(path){location.hash=path;}
const route=()=>location.hash.slice(1).split('/').filter(Boolean);const subject=id=>subjects.find(s=>s.id===id)||subjects[0];
function hero(tag,title,sub,tone='green',art='study'){return `<section class="hero ${tone}"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${sub}</p></div><div class="hero-art">${art==='study'?'<img src="./assets/study.png" alt="Books and study calendar">':`<img src="./assets/${art==='quiz'?'quiz':art==='paper'?'paper':'study'}.png" alt="">`}</div></section>`;}
function profileInitial(){return esc(Array.from(state.profile?.name.trim()||'?')[0].toLocaleUpperCase());}
function profileButton(){return link(`<span aria-hidden="true">${profileInitial()}</span><span class="sr-only">My Profile</span>`,'/profile','round profile-link profile-initial');}
function top(title,sub=''){return `<header class="subheader"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${profileButton()}</header>`;}
function header(){const unread=unreadCount();return `<header class="main-header"><a class="wordmark" href="#/home"><img src="./assets/logo-horizontal.png" alt="BEU Exam Dost" class="brand-logo-light"><img src="./assets/logo-horizontal-dark.png" alt="BEU Exam Dost" class="brand-logo-dark"><span class="sr-only">BEU Exam Dost</span></a><div class="header-actions"><a class="round notif-btn" href="#/notifications" aria-label="What's new${unread>0?' · '+unread+' unread':''}">${icon('bell')}${unread>0?'<span class="notif-pip" aria-hidden="true"></span>':''}</a>${profileButton()}</div></header>`;}
function nav(active,extraClass='',backPath=null){const items=[['home','Home','/home'],['subjects','Subjects','/subjects'],['pyqs','PYQs','/pyqs'],['quiz','Quiz','/quiz','mobile-quiz'],['quiz-pyq','PYQ Quiz','/quiz/pyq','desktop-only-nav-item'],['quiz-master','Master Quiz','/quiz/master','desktop-only-nav-item'],['planner','Planner','/planner','desktop-only-nav-item'],['notifications','Notifications','/notifications','desktop-only-nav-item']];const currentIndex=items.findIndex(([id])=>id===active);const previousIndex=nav.previousIndex;const direction=previousIndex===undefined||currentIndex===previousIndex?'none':currentIndex>previousIndex?'down':'up';if(currentIndex>=0)nav.previousIndex=currentIndex;const name=state.profile?.name||'My profile';const brand=`<a class="desktop-brand-top" href="#/home" aria-label="BEU Exam Dost home"><img class="brand-logo-light" src="./assets/logo-horizontal.png" alt="BEU Exam Dost"><img class="brand-logo-dark" src="./assets/logo-horizontal-dark.png" alt=""></a>`;const links=items.map(([id,t,path,extra=''])=>link(`${['home','subjects','pyqs','quiz','quiz-pyq','quiz-master'].includes(id)?`<img class="nav-icon-3d" src="./assets/nav-${id.startsWith('quiz-')?'quiz':id}.webp" alt="" width="32" height="32">`:id==='planner'?'<img class="nav-icon-3d" src="./assets/nav-planner.svg" alt="" width="32" height="32">':'<img class="nav-icon-3d" src="./assets/nav-notifications.svg" alt="" width="32" height="32">'}<span>${t}</span>${id==='notifications'&&unreadCount()?'<i class="desktop-nav-unread" aria-hidden="true"></i>':''}`,path,`${active===id?'active ':''}${extra}`.trim(),`aria-label="${t}" title="${t}"`)).join('');const railBack=backPath?link(icon('back')+'<span>Back</span>',backPath,'desktop-rail-back','aria-label="Back" title="Back"'):'';const profile=link(`<span class="desktop-rail-avatar" aria-hidden="true">${profileInitial()}</span><span class="desktop-rail-profile-copy"><b>${esc(name)}</b><small>My profile</small></span>`,'/profile','desktop-rail-profile',`aria-label="${esc(name)} · My profile" title="My profile"`);return `<div class="desktop-nav-assembly">${brand}<nav class="bottom-nav desktop-side-nav ${extraClass}" aria-label="Main navigation" data-nav-direction="${direction}"><div class="desktop-rail-links">${links}</div>${railBack}${profile}</nav></div>`;}
function back(path='/home'){return `<div class="back-dock">${link(icon('back')+' Back',path,'back-pill')}</div>`;}
function page(html,{active=null,parent='/home',main=false}={}){const desktopActive=active||primaryNavForRoute()||'profile';const backPath=parent==='/home'?null:parent;const desktopRail=desktopActive?nav(desktopActive,active?'':'desktop-side-nav--subpage',backPath):'';return `<div class="app-shell ${main?'home-shell':'content-shell'}">${main?header():''}${!active?back(parent):''}<main id="main">${html}</main>${desktopRail}</div>`;}
function percent(ts){let done=ts.filter(t=>state.topics[t.id]).length;return {done,total:ts.length,pct:ts.length?Math.round(done/ts.length*100):0};}
function bar(p,color='green'){return `<div class="progress-track ${color}" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div>`;}
function ring(p){return `<div class="ring" style="--p:${p}"><b>${p}%</b></div>`;}
function subjectCards(target,sub=''){return `<div class="subject-list">${subjects.map(s=>{let p=percent(s.units.flatMap(u=>u.topics));return link(`<span class="subject-icon ${s.color}">${icon(s.icon)}</span><div class="subject-content"><span class="badge ${s.color}">${s.short}</span><h3>${s.name}</h3><p>${sub||`${p.done} of ${p.total} topics completed`}</p>${sub?'':bar(p.pct,s.color)}</div>${icon('chevron')}`,target(s),'subject-card card');}).join('')}</div>`;}
function onboardingCopyright(){return `<footer class="onboarding-copyright">© ${new Date().getFullYear()} BEU Developer. All rights reserved.</footer>`;}
function desktopWelcomePage(){const social={linkedin:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7.5 10v7M7.5 7v.1M11 17v-7m0 3a3 3 0 0 1 6 0v4"/></svg>',website:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/></svg>',mail:icon('mail')};return `<div class="onboarding-shell onboarding-welcome"><header class="onboarding-top"><a class="onboarding-brand" href="#/welcome" aria-label="BEU Exam Dost home"><img class="onboarding-logo-light" src="./assets/logo-horizontal.png" alt="BEU Exam Dost"><img class="onboarding-logo-dark" src="./assets/logo-horizontal-white.png" alt="BEU Exam Dost"></a></header><main class="onboarding-grid"><section class="onboarding-hero"><div class="onboarding-hero-copy"><span class="onboarding-pill onboarding-live"><i aria-hidden="true"></i>DESKTOP IS NOW LIVE</span><h1>BEU Exam Dost is now on desktop.</h1><p>Connect your BEU Exam Dost profile and study PYQs, notes and quizzes on a bigger screen.</p><a class="onboarding-cta" href="#/sync-login">Continue to desktop ${icon('arrow')}</a></div><div class="onboarding-illustration" aria-hidden="true"><img src="./assets/desktop-welcome-illustration.svg" alt=""></div></section><aside class="onboarding-updates"><span class="onboarding-pill"><span class="onboarding-whatsapp-pill-icon" aria-hidden="true"><img src="./assets/whatsapp-brand-icon.svg" alt=""></span>WHATSAPP CHANNEL</span><span class="onboarding-whatsapp-art" aria-hidden="true"><img src="./assets/whatsapp-brand-icon.svg" alt=""></span><h2>Connect with us</h2><p>Join our WhatsApp channel for exam updates, new PYQs and app news.</p><a class="onboarding-whatsapp" href="https://whatsapp.com/channel/0029Vb9TLSv3QxS3HzyEOf1v" target="_blank" rel="noopener noreferrer">View WhatsApp channel ${icon('arrow')}</a></aside><div class="onboarding-welcome-lower"><div class="onboarding-left-lower"><section class="onboarding-stats"><div><span class="onboarding-stat-icon">${icon('network')}</span><span class="onboarding-stat-copy"><b>6</b><span>Core subjects</span></span></div><div><span class="onboarding-stat-icon">${icon('grid')}</span><span class="onboarding-stat-copy"><b>36</b><span>Syllabus units</span></span></div><div><span class="onboarding-stat-icon">${icon('database')}</span><span class="onboarding-stat-copy"><b>70</b><span>Theory marks</span></span></div></section><section class="onboarding-subjects" aria-label="Subjects"><div>${subjects.concat(subjects).map(s=>`<span><span class="onboarding-subject-badge"><span class="onboarding-subject-icon">${icon(s.icon)}</span><b>${esc(s.short)}</b></span>${esc(s.name)}</span>`).join('')}</div></section></div><section class="onboarding-developer"><span class="onboarding-pill">ABOUT THE DEVELOPER</span><h2>BEU Developer</h2><div><a href="${esc(socialLinks.linkedin)}" target="_blank" rel="noopener noreferrer">${social.linkedin}<span>LinkedIn</span></a><a href="mailto:beudeveloper@gmail.com">${social.mail}<span>Email</span></a><a href="https://beudeveloper.in/" target="_blank" rel="noreferrer">${social.website}<span>Website</span></a></div></section></div></main><p class="onboarding-foot">No account needed. Set up once on this device.</p>${onboardingCopyright()}</div>`;}
function syncLoginPage(){const pin=syncLoginMode==='pin',pending=syncClient.pendingPairing(),pinPending=pin&&pending?.method==='pin'&&pending.expiresAt>Date.now();const inputs=Array.from({length:4},(_,i)=>`<input class="onboarding-pin-input" data-pin-digit inputmode="numeric" pattern="[0-9]*" autocomplete="one-time-code" maxlength="1" aria-label="PIN digit ${i+1}">`).join('');const pinBody=pinPending?`<div id="pairing-status-region" class="pairing-status-region"><h3>PIN submitted</h3><p id="pairing-status"><span id="pairing-wait-label">Waiting for approval on your primary device</span> · <span id="pairing-countdown">${countdownLabel(pending.expiresAt)}</span> remaining</p><button class="button danger pairing-cancel" data-action="sync-cancel">Cancel pairing</button></div>`:`<div class="onboarding-pin-entry" role="group" aria-label="Four digit pairing PIN">${inputs}</div><div class="onboarding-sync-instructions"><h3>Generate the PIN in BEU Exam Dost</h3><ol><li>Open BEU Exam Dost on your primary device</li><li>Go to Profile → Linked devices</li><li>Choose Generate desktop PIN and enter it here</li></ol></div><div class="onboarding-sync-choice"><button class="onboarding-cta" data-action="sync-page-pin-submit">Submit PIN ${icon('arrow')}</button><button class="onboarding-text-button" data-action="sync-use-qr">Use QR code instead</button></div>`;return `<div class="onboarding-shell onboarding-split"><header class="onboarding-top"><a class="onboarding-brand" href="#/welcome" aria-label="BEU Exam Dost home"><img class="onboarding-logo-light" src="./assets/logo-horizontal.png" alt="BEU Exam Dost"><img class="onboarding-logo-dark" src="./assets/logo-horizontal-white.png" alt="BEU Exam Dost"><span>Desktop workspace</span></a></header><main class="onboarding-split-grid"><section class="onboarding-sync-panel"><span class="onboarding-pill onboarding-sync-pill">SECURE DEVICE SYNC</span><h1>${pin?'Connect with a PIN.':'Connect your BEU Exam Dost profile.'}</h1><p>${pin?'Enter the four-digit PIN generated in BEU Exam Dost on your primary device.':'Use BEU Exam Dost on your primary device to scan the desktop QR code and approve this connection.'}</p>${pin?pinBody:`<div class="onboarding-sync-content"><div id="pairing-qr-slot" class="onboarding-qr-placeholder"><span>QR</span></div><div class="onboarding-sync-instructions"><h3>Pair in three steps</h3><ol><li>Open BEU Exam Dost on your primary device</li><li>Go to Profile → Linked devices → Scan desktop QR</li><li>Scan this QR code and approve the desktop</li></ol><div id="pairing-status-region" aria-live="polite"></div></div></div><div class="onboarding-sync-choice"><button class="onboarding-cta" data-action="sync-link-account">Display pairing QR ${icon('arrow')}</button><button class="onboarding-ghost" data-action="sync-use-pin">Use PIN instead</button></div>`}</section><section class="onboarding-benefit-panel"><span class="onboarding-pill">DESKTOP STUDY SPACE</span><h2>Practice with purpose, wherever you study.</h2><p>Your BEU Exam Dost profile stays on your primary device while this desktop gives you room to focus.</p><div class="onboarding-sync-art" aria-hidden="true"><img src="./assets/desktop-pairing-illustration.svg" alt=""></div><a class="onboarding-cta" href="#/create-account">Create a new profile ${icon('arrow')}</a></section></main>${onboardingCopyright()}</div>`;}
function createAccountPage(){let p=state.profile||{},legacyBranches={'CSE (Artificial Intelligence & Machine Learning)':branches[4],'CSE (Data Science)':branches[5],'CSE (Cyber Security)':branches[2],'CSE (Internet of Things)':branches[3]},selectedBranch=legacyBranches[p.branch]||p.branch||'',selectedCollege=p.college||'';return `<div class="onboarding-shell onboarding-split"><header class="onboarding-top"><a class="onboarding-brand" href="#/welcome" aria-label="BEU Exam Dost home"><img class="onboarding-logo-light" src="./assets/logo-horizontal.png" alt="BEU Exam Dost"><img class="onboarding-logo-dark" src="./assets/logo-horizontal-white.png" alt="BEU Exam Dost"><span>Desktop workspace</span></a></header><main class="onboarding-split-grid"><section class="onboarding-benefit-panel onboarding-profile-benefit"><span class="onboarding-pill">YOUR STUDY COMPANION</span><h2>Bring your BEU Exam Dost profile to desktop.</h2><p>Already have a BEU Exam Dost profile? Connect it to this desktop with a QR code or PIN.</p><div class="onboarding-mobile-art" aria-hidden="true"><span class="onboarding-mobile-art-phone"></span><span class="onboarding-mobile-art-check">✓</span></div><a class="onboarding-ghost onboarding-wide-link" href="#/sync-login">Connect an existing device ${icon('arrow')}</a></section><section class="onboarding-form-panel"><h1>Create your profile</h1><form id="profile-form" class="onboarding-profile-form"><label>Your name<input name="name" required maxlength="100" placeholder="Enter your name" autocomplete="name" value="${esc(p.name||'')}"></label><label>College<select name="college" required id="college-select"><option value="">Select your college</option>${selectedCollege&&!colleges.includes(selectedCollege)?`<option value="${esc(selectedCollege)}" selected>${esc(selectedCollege)}</option>`:''}${colleges.map(c=>`<option value="${esc(c)}" ${selectedCollege===c?'selected':''}>${esc(c)}</option>`).join('')}<option value="Other Engineering College" ${selectedCollege==='Other Engineering College'?'selected':''}>Other Engineering College</option></select></label><label>Branch<select name="branch" required><option value="">Select your branch</option>${selectedBranch&&!branches.includes(selectedBranch)?`<option selected>${esc(selectedBranch)}</option>`:''}${branches.map(b=>`<option ${selectedBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><button class="onboarding-cta" type="submit">Create profile ${icon('arrow')}</button></form></section></main>${onboardingCopyright()}</div>`;}
function setup(edit=false){let p=state.profile||{};let cached=(!edit&&!forceFreshSetup)?getCachedProfile():null;if(cached&&cached.name&&!edit){return `<div class="app-shell setup-shell"><main><div class="wordmark setup-brand"><img src="./assets/logo-horizontal.png" alt="BEU Exam Dost" class="brand-logo-light"><img src="./assets/logo-horizontal-dark.png" alt="BEU Exam Dost" class="brand-logo-dark"><span class="sr-only">BEU Exam Dost</span></div><section class="card welcome-back-card"><h2>👋 Welcome Back!</h2><p class="muted">We found your saved study profile on this device:</p><div class="welcome-actions">${btn('Continue as '+esc(cached.name.split(' ')[0])+' &rarr;','continue-profile','button primary full')}${!['Android','iOS'].includes(getDeviceInfo().os)?btn('Connect existing profile','sync-link-account','button outline full'):''}${btn('Start Fresh (Create New Profile)','fresh-start','button outline full')}</div></section></main></div>`;}const legacyBranches={'CSE (Artificial Intelligence & Machine Learning)':branches[4],'CSE (Data Science)':branches[5],'CSE (Cyber Security)':branches[2],'CSE (Internet of Things)':branches[3]};const selectedBranch=legacyBranches[p.branch]||p.branch;const selectedCollege=p.college||'';return `<div class="app-shell setup-shell">${edit?nav('profile','desktop-side-nav--subpage','/profile'):''}<main>${!edit?'<div class="wordmark setup-brand"><img src="./assets/logo-horizontal.png" alt="BEU Exam Dost" class="brand-logo-light"><img src="./assets/logo-horizontal-dark.png" alt="BEU Exam Dost" class="brand-logo-dark"><span class="sr-only">BEU Exam Dost</span></div>':top('Edit profile')}${hero('YOUR STUDY COMPANION',edit?'Make it yours.':getDeviceInfo().os==='Windows'?'Welcome to BEU Exam Dost on Windows.':'Your exam journey<br>starts here.',edit?'Tell us a little about yourself.':getDeviceInfo().os==='Windows'?'Your desktop study space is ready. Set up here or connect your existing profile.':'Tell us a little about yourself.','blue')}${!edit&&!['Android','iOS'].includes(getDeviceInfo().os)?`<p class="desktop-connect-prompt">${btn('Connect to phone','sync-link-account','button outline')} ${btn('Install app','install','button outline')}</p>`:''}<form id="profile-form" class="card form-card"><h2>${edit?'Your details':'Set up your profile'}</h2><label>Your name<input name="name" required maxlength="100" placeholder="Enter your name" autocomplete="name" value="${esc(p.name||'')}"></label><label>College<select name="college" required id="college-select"><option value="">Select your college</option>${selectedCollege&&!colleges.includes(selectedCollege)?`<option value="${esc(selectedCollege)}" selected>${esc(selectedCollege)}</option>`:''}${colleges.map(c=>`<option value="${esc(c)}" ${selectedCollege===c?'selected':''}>${esc(c)}</option>`).join('')}<option value="Other Engineering College" ${selectedCollege==='Other Engineering College'?'selected':''}>Other Engineering College</option></select></label><label>Branch<select name="branch" required><option value="">Select your branch</option>${selectedBranch&&!branches.includes(selectedBranch)?`<option selected>${esc(selectedBranch)}</option>`:''}${branches.map(b=>`<option ${selectedBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><p class="muted small">All 58 BEU affiliated colleges available. CSE and supported specialisation branches share the same study content.</p><button class="primary full">${edit?'Save changes':'Get started'} ${icon('arrow')}</button></form><p class="footnote">No account needed. Set up once on this device.</p></main>${edit?back('/profile'):''}</div>`;}
function home(){let p=percent(allTopics),today=dateKey();let tasks=state.tasks.filter(t=>t.date===today).slice(0,3);let upcoming=subjects.filter(s=>examDates[s.id]&&examDates[s.id]>=today).sort((a,b)=>examDates[a.id].localeCompare(examDates[b.id]))[0];let days=upcoming?Math.ceil((new Date(examDates[upcoming.id]+'T00:00:00')-new Date(today+'T00:00:00'))/86400000):0;return page(`${hero('YOUR STUDY COMPANION','A little progress,<br>every day.',`Let’s make today count, ${esc(state.profile.name.split(' ')[0])}.`)}<section class="card next-exam"><div><span class="badge green">Next exam</span><h2>${upcoming?upcoming.name:'Exams complete. Well done.'}</h2><p>${upcoming?`${days===0?'Today':days+' days to go'} · ${formatDate(examDates[upcoming.id])} · ${examSession.label}`:'Your scheduled exams have finished. Keep learning at your own pace.'}</p>${link('View exam schedule '+icon('arrow'),'/planner','text-link')}</div><span class="calendar-art">${upcoming?`<strong>${days}</strong><small>DAYS</small>`:icon('calendar')}</span></section><section class="card summary mint"><div><h2>Your preparation</h2><p>${p.done} of ${p.total} topics completed</p>${bar(p.pct)}</div>${ring(p.pct)}${desktopSubjectProgress()}</section><div class="section-heading"><h2>Today’s plan</h2>${link('View all '+icon('arrow'),'/planner','text-link')}</div>${tasks.length?`<section class="card task-list">${tasks.map(taskRow).join('')}</section>`:`<section class="card empty"><span class="subject-icon green">${icon('calendar')}</span><h3>A fresh start awaits.</h3><p>Choose your study time and build today’s plan.</p>${link('Plan my preparation','/planner','button primary')}</section>`}<div class="section-heading"><h2>Keep learning</h2></div><div class="shortcut-grid">${link(icon('document')+'<div><h3>Important PYQs</h3><p>Questions that matter</p></div>','/pyqs','shortcut mint')}${link(icon('trophy')+'<div><h3>Master Quiz</h3><p>Test your concepts</p></div>','/quiz/master','shortcut lavender')}</div><p class="footnote">Your progress stays on this device.</p>`,{active:'home',main:true});}
function subjectsPage(){let p=percent(allTopics);return page(`${hero('YOUR SYLLABUS','My Subjects','One topic at a time. You’ve got this.')}<section class="card summary"><div><p>Overall syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>6 subjects · Your progress, in one place</p></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your subjects</h2><span>6 subjects</span></div>${subjectCards(s=>'/subjects/'+s.id)}`,{active:'subjects',main:true});}
function subjectPage(id){let s=subject(id),p=percent(s.units.flatMap(u=>u.topics));return page(`${top(s.name,'Subjects / Unit overview')}${hero(s.short+' · SUBJECT OVERVIEW',s.name,'Build concepts. Track every topic.',s.color)}<section class="card summary"><div><p>Your syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><span class="badge green">6 units</span> <span class="muted small">${p.total-p.done} topics remaining</span></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your units</h2><span>Tap a unit to explore</span></div><div class="unit-list">${s.units.map(u=>{let x=percent(u.topics);return link(`<span class="unit-no ${u.color}">${String(u.id).padStart(2,'0')}</span><div class="unit-content"><div class="unit-title"><h3>${u.title}</h3>${u.important?'<span class="badge coral">☆ Important unit</span>':''}</div><p>${u.topics.map(t=>t.title).join(' · ')}</p><div class="unit-status"><small>${x.done} of ${x.total} topics</small><span class="badge ${x.pct===100?'green':'neutral'}">${x.pct===100?'✓ Completed':x.done?'In progress':'Not started'}</span></div>${bar(x.pct,u.color)}</div>${icon('chevron')}`,`/subjects/${s.id}/${u.id}`,'card unit-card');}).join('')}</div>`,{parent:'/subjects'});}
function unitPage(id,num){let s=subject(id),u=s.units.find(u=>u.id===+num)||s.units[0],p=percent(u.topics);let list=u.topics.filter(t=>unitFilter==='all'||(unitFilter==='done'?state.topics[t.id]:!state.topics[t.id]));return page(`${top(s.name,`Unit ${String(u.id).padStart(2,'0')} of 06`)}<div class="right-link">${link(icon('grid')+' All units','/subjects/'+s.id,'text-link')}</div>${hero('UNIT '+String(u.id).padStart(2,'0'),u.title,'Your topic checklist',u.color)}<section class="card summary"><div><p>Unit progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>${p.total-p.done} topics left to cover</p></div>${ring(p.pct)}</section><div class="chips">${[['all',`All (${p.total})`],['pending',`Pending (${p.total-p.done})`],['done',`Completed (${p.done})`]].map(([v,t])=>btn(t,'unit-filter','chip '+(unitFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><div class="section-heading"><h2>Topic checklist</h2></div><p class="muted small">Tick a topic when you finish studying.</p><div class="topics">${list.map(t=>`<label class="card topic"><input type="checkbox" data-topic="${t.id}" ${state.topics[t.id]?'checked':''}><span class="check-ui">${icon('check')}</span><span class="topic-title">${t.title}</span><span class="badge ${state.topics[t.id]?'green':t.important?'coral':'neutral'}">${state.topics[t.id]?'✓ Done':t.important?'High priority':'Study'}</span></label>`).join('')||'<div class="card empty">No topics in this filter.</div>'}</div><div class="unit-travel">${u.id>1?link(icon('back')+`<div>Previous unit<small>${s.units[u.id-2].title}</small></div>`,`/subjects/${s.id}/${u.id-1}`,'button outline'):''}${link(`<div>${u.id<6?'Next unit':'All units'}<small>${u.id<6?s.units[u.id].title:'Back to the overview'}</small></div>`+icon('arrow'),u.id<6?`/subjects/${s.id}/${u.id+1}`:'/subjects/'+s.id,'button primary')}</div>`,{parent:'/subjects/'+s.id});}
function pyqIndex(){return page(`${hero('PREVIOUS YEAR QUESTIONS','Practice with purpose.','Important 7-mark written questions, organised by subject.','orange','paper')}<div class="card notice">${icon('document')}<div><h3>Official 7-Mark Written PYQs</h3><p>Browse by unit and see Bihar Engineering University paper-year trends.</p></div></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>'/pyqs/'+s.id,'View important questions')}`,{active:'pyqs',main:true});}
function renderSolution(sol,totalMarks,q){if(!sol)return"";return`<div class="solution-panel" id="solution-${sol.id||"panel"}"><div class="solution-header"><span class="badge verified-pill">${esc(sol.verified||"BEU Verified Model Answer · 7 Marks")}</span><span class="solution-tagline">Senior PYQ Solver Model Solution</span>${q?btn(icon('download')+' Download 1-Page A4 PDF','download-pdf','button small download-solution-btn',`data-id="${q.id}" title="Download 1-Page A4 PDF"`):''}</div>${sol.intro?`<div class="solution-intro"><p>${sol.intro}</p></div>`:""}${sol.diagrams&&sol.diagrams.length?sol.diagrams.map(diag=>`<div class="solution-diagram-card"><div class="diagram-header"><span class="diagram-tag">PICTORIAL REPRESENTATION</span><span class="diagram-title">${esc(diag.title)}</span></div><div class="ascii-scroll-container"><pre class="solution-ascii">${esc(diag.ascii)}</pre></div></div>`).join(""):""}${sol.table?`<div class="solution-table-card"><h5>${esc(sol.table.title)}</h5><div class="table-scroll"><table class="solution-table"><thead><tr>${sol.table.headers.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${sol.table.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`:""}${sol.sections&&sol.sections.length?sol.sections.map(sec=>`<div class="solution-section"><h4>${esc(sec.heading)}</h4><ul class="solution-points">${sec.points.map(pt=>`<li>${pt}</li>`).join("")}</ul></div>`).join(""):""}${sol.conclusion?`<div class="solution-conclusion"><p><b>Conclusion:</b> ${sol.conclusion}</p></div>`:""}${sol.markingScheme&&sol.markingScheme.length?`<div class="marking-scheme-card"><div class="marking-header"><span class="marking-icon">📋</span><h5>Suggested Point-wise Marking Guide</h5></div><div class="table-scroll"><table class="marking-table"><thead><tr><th style="text-align:left;">Evaluation Component</th><th style="width:90px;text-align:right;">Marks</th></tr></thead><tbody>${sol.markingScheme.map(m=>`<tr><td style="text-align:left;">${esc(m.component)}</td><td style="text-align:right;font-weight:700;color:var(--forest);">${esc(m.marks)}</td></tr>`).join("")}</tbody><tfoot><tr><th style="text-align:left;">Total Question Marks</th><th style="text-align:right;color:var(--forest);font-weight:800;">${totalMarks}.0</th></tr></tfoot></table></div></div>`:""}${sol.examTip?`<div class="exam-tip-card"><span class="exam-tip-badge">💡 Senior Solver Exam Tip</span><p>${esc(sol.examTip)}</p></div>`:""}</div>`;}
function pyqSubject(id){let s=subject(id),all=pyqs(s.id);let originalItems=all.filter(q=>q.kind==='original');let effectiveKind=pyqKind||(originalItems.length?'original':'important');let years=[...new Set(originalItems.map(q=>q.source?.year).filter(Boolean))].sort((a,b)=>b-a);if(!years.length)years=[2024,2023,2022];let counts=yearCounts(originalItems,years);let list=filterWrittenQuestions(all,{kind:effectiveKind,unit:unitFilter,year:pyqYear,savedOnly,saved:state.saved});let kindTitle=effectiveKind==='original'?'Original PYQs':'Important 7-Mark Questions';return page(`${top(s.name,kindTitle)}${hero(s.short+' · QUESTION BANK',kindTitle,'Unit-wise questions & verified solutions.','orange','paper')}${renderQuestionFilters({kind:effectiveKind,unit:unitFilter,year:pyqYear,units:s.units,years,savedOnly})}<div class="section-heading"><h2>${effectiveKind==='original'?'Verified Original Exam Questions':'Important 7-Mark Model Questions'}</h2><span>${list.length} questions available</span></div><div class="pyq-list">${list.map(q=>{let isOpen=openSolutions.has(q.id);let uTitle=(s.units[q.unit-1]&&s.units[q.unit-1].title)?s.units[q.unit-1].title:'Core Subject Module';let sourceChip=esc(questionSourceLabel(q));return `<article class="card pyq-card" id="card-${q.id}"><div class="pyq-title"><span class="badge ${colors[(q.unit-1)%colors.length]}">Unit ${String(q.unit).padStart(2,'0')}</span><h3>${esc(uTitle)}</h3><span class="badge neutral verified-chip">${sourceChip}</span></div><p class="question-text">${esc(q.question)}</p><div class="years"><span class="badge orange">${q.marks||7} marks</span>${q.source?.year?`<span class="muted small">Asked in</span><span class="badge orange">${q.source.year}</span>`:''}</div><div class="pyq-actions">${btn(icon(state.marked.includes(q.id)?'check':'grid')+(state.marked.includes(q.id)?' Marked':' Mark'),'mark','text-link',`data-id="${q.id}" aria-pressed="${state.marked.includes(q.id)}"`)}${q.solution?btn(icon('document')+(isOpen?' Hide Solution':' View '+(q.marks||7)+'-Mark Solution'),'toggle-solution','button small '+(isOpen?'is-active':'outline-solution'),`data-id="${q.id}" aria-expanded="${isOpen}"`):''}${q.solution?btn(icon('download')+' PDF','download-pdf','button small outline-pdf',`data-id="${q.id}" title="Download 1-Page A4 PDF Solution"`):''}${btn(icon('save')+(state.saved.includes(q.id)?' Saved':' Save'),'save-question','text-link '+(state.saved.includes(q.id)?'amber':''),`data-id="${q.id}" aria-pressed="${state.saved.includes(q.id)}"`)}</div>${isOpen?renderSolution(q.solution,q.marks||7,q):''}</article>`;}).join('')||`<div class="card empty">${esc(questionEmptyState(effectiveKind,savedOnly))}</div>`}</div>${effectiveKind==='original'?`<section class="card analysis"><h2>Unit-wise year analysis</h2><p class="muted small">Recurrence frequency across recent Bihar Engineering University question papers.</p><div class="table-scroll"><table><thead><tr><th>Unit</th>${years.map(y=>`<th>${y}</th>`).join('')}<th>Total</th></tr></thead><tbody>${counts.map((row,i)=>`<tr><th>${String(i+1).padStart(2,'0')}</th>${row.map(n=>`<td>${n}</td>`).join('')}<td><b>${row.reduce((a,b)=>a+b,0)}</b></td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th>${years.map((_,j)=>`<td>${counts.reduce((a,r)=>a+r[j],0)}</td>`).join('')}<td>${counts.flat().reduce((a,b)=>a+b,0)}</td></tr></tfoot></table></div><p class="small muted">Unit classification follows the official BEU B.Tech CSE syllabus. Topics with higher frequencies represent primary exam targets.</p></section>`:`<section class="card analysis"><h2>Syllabus-Aligned Practice</h2><p class="muted small">Syllabus-aligned practice; not claimed as a previous paper question.</p></section>`}`,{parent:'/pyqs'});}
function quizIndex(){return page(`${hero('QUIZ ZONE','Test yourself.<br>Grow stronger.','Choose your quiz type to get started.','purple','quiz')}<div class="section-heading"><h2>How would you like to practise?</h2></div><p class="muted">Pick a quiz type. Choose your subject next.</p>${[['pyq','FROM EXAM PAPERS','PYQ MCQ Quiz','Attempt original MCQs from previous-year question papers.','orange','paper','Year-wise questions · Answer explanations'],['master','SYLLABUS-BASED PRACTICE','Syllabus Master Quiz','Challenge your concepts with advanced syllabus-based MCQs.','purple','quiz','Unit-wise coverage · Mistake review']].map(([id,tag,title,sub,tone,art,features])=>link(`<span class="eyebrow">${tag}</span><img class="mode-art" src="./assets/${art==='paper'?'paper':'quiz'}.png" alt=""><h2>${title}</h2><p>${sub}</p><span class="mode-features">${features}</span><strong>Choose subject ${icon('arrow')}</strong>`,'/quiz/'+id,'card mode-card '+tone)).join('')}<p class="footnote">Your quiz progress stays on this device.</p>`,{active:'quiz-pyq',main:true});}
function quizSubjects(type){let master=type==='master';return page(`${top(master?'Syllabus Master Quiz':'PYQ MCQ Quiz','Quiz / Choose subject')}${hero(master?'SYLLABUS-BASED PRACTICE':'FROM PREVIOUS-YEAR PAPERS',master?'Go beyond memorising.':'Pick a subject.<br>Take the challenge.',master?'Understand. Apply. Master.':'Original exam MCQs, organised by subject.',master?'purple':'orange',master?'quiz':'paper')}<div class="card features"><span>${icon(master?'book':'calendar')}${master?'Unit-wise coverage':'Year-wise MCQs'}</span><span>${icon('info')}Explanations & review</span></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>`/quiz/${type}/${s.id}`,master?'Advanced syllabus-based MCQs':'Original previous-year paper MCQs')}<p class="footnote">${master?'Syllabus-aligned master practice questions':'Original previous-year paper MCQs with step-by-step explanations'}</p>`,{parent:matchMedia('(min-width: 861px)').matches?'/home':'/quiz'});}
function weightageSection(subjectId){let list=unitWeightage[subjectId];if(!list||!list.length)return '';let totalMarks=list.reduce((n,w)=>n+w.marks,0)||70;let segColors=['#10b981','#3b82f6','#8b5cf6','#f97316','#14b8a6','#eab308'];return `<section class="weightage-section"><div class="section-heading"><h2>Exam Weightage & Concept Flow</h2><span>BEU Unit Distribution</span></div><div class="weightage-meter-wrap"><div style="display:flex;justify-content:space-between;align-items:center;"><b>Subject Marks Distribution</b><span class="badge purple">${totalMarks} Marks Evaluated</span></div><div class="weightage-meter" role="progressbar" aria-label="Unit marks weightage" aria-valuenow="100" aria-valuemin="0" aria-valuemax="100">${list.map((w,i)=>`<div class="weightage-segment" style="width:${(w.marks/totalMarks*100).toFixed(1)}%;background:${segColors[i%segColors.length]};" title="Unit ${w.unit}: ${w.marks} marks (${Math.round(w.marks/totalMarks*100)}%)"></div>`).join('')}</div><div class="weightage-legend">${list.map((w,i)=>`<span class="weightage-legend-item"><span class="legend-dot" style="background:${segColors[i%segColors.length]}"></span>Unit ${w.unit} (${w.marks}M · ${Math.round(w.marks/totalMarks*100)}%)</span>`).join('')}</div></div><div class="section-heading"><h2>Unit-Wise Topic Roadmap</h2><span>Chronological Flow</span></div><div style="display:flex;flex-direction:column;gap:0.85rem;">${list.map(w=>`<div class="flow-card"><div class="flow-header"><span class="badge ${colors[(w.unit-1)%colors.length]}">Unit ${w.unit}</span><h4>${esc(w.title)}</h4><span class="badge ${w.priority==='CRITICAL'?'coral':w.priority==='VERY HIGH'?'orange':'green'}">${w.priority}</span><span class="flow-marks">${w.marks} Marks</span></div><div class="flow-path"><span class="flow-label">Question & Concept Flow</span><p class="flow-text">${esc(w.flow)}</p></div><div class="flow-meta"><span>${w.mcqs} High-Yield MCQs · ${w.pyqs} Written Questions (7M)</span>${btn('Practice Unit '+icon('arrow'),'practice-unit','button outline small-btn',`data-subject="${subjectId}" data-unit="${w.unit}"`)}</div></div>`).join('')}</div></section>`;}
function quizSets(type,id){let s=subject(id),master=type==='master',a=state.attempts.find(a=>a.subject===s.id&&a.type===type&&!a.finished);let availableYears=pyqMcqYears(s.id);return page(`${top(s.name,master?'Syllabus Master Quiz / Set up':'PYQ MCQ Quiz / Choose paper')}${hero(s.short+' · '+(master?'MASTER QUIZ':'PYQ MCQ QUIZ'),master?'Ready for a challenge?':'Learn from past papers.',master?'Choose your units and focus time.':'Choose a paper year to begin.',master?'purple':'orange',master?'quiz':'paper')}${a?`<div class="card resume"><h3>You have an unfinished quiz</h3><p>Your answers and active time are saved.</p>${link('Resume quiz '+icon('arrow'),'/attempt/'+a.id,'button primary')}</div>`:''}${master?`<form id="quiz-setup" class="card form-card" data-subject="${s.id}"><h2>Make this session yours</h2><label>Units<select name="unit"><option value="all">All units</option>${s.units.map(u=>`<option value="${u.id}">Unit ${u.id} · ${u.title}</option>`).join('')}</select></label><label>Time limit<select name="minutes"><option value="10">10 minutes</option><option value="20" selected>20 minutes</option><option value="30">30 minutes</option><option value="0">No limit · elapsed timer</option></select></label><div class="notice"><span>${quizQuestions(s.id,'master').length} syllabus practice questions available across 6 units.</span></div><button class="primary full">Start master quiz ${icon('arrow')}</button></form>`:availableYears.length?`<div class="section-heading"><h2>Year-wise quiz sets</h2><span>Official papers</span></div>${availableYears.map((y,i)=>{let count=quizQuestions(s.id,'pyq',y).length;return `<article class="card paper-card"><div class="year-tile ${colors[i%colors.length]}">${icon('calendar')}<strong>${y}</strong></div><div><h2>${y} Paper</h2><p>Original BEU Question Paper</p><span class="badge orange">${count} original MCQs</span></div>${btn('Start quiz '+icon('arrow'),'start-pyq','button amber-button',`data-subject="${s.id}" data-year="${y}"`)}</article>`;}).join('')}`:`<div class="card empty"><span class="subject-icon orange">${icon('document')}</span><h3>Official Objective Papers Pending</h3><p>Official objective papers for ${s.name} were not present in the scanned bundle. Practice with the comprehensive 50-Question Master Mock instead.</p>${link('Start Master Mock '+icon('arrow'),'/quiz/master/'+s.id,'button primary')}</div>`}<div class="card notice">${icon('info')}<span>${master?'Answers and detailed explanations appear after submission.':'Original previous-year paper MCQs. Attempt under exam timing and review solutions.'}</span></div>${weightageSection(s.id)}`,{parent:'/quiz/'+type});}
function activeAttempt(){return state.attempts.find(a=>a.id===route()[1]);}
function startAttempt(s,type,year=null,unit='all',minutes=20,previousQuestions=null){let pool=quizQuestions(s,type,year);let questions=previousQuestions||(type==='master'?pool.filter(q=>unit==='all'||q.unit===+unit):pool);if(!questions.length){toast('No questions for this selection yet.');return;}let a={id:uid(),subject:s,type,year,questions,answers:questions.map(()=>null),times:questions.map(()=>0),index:0,startedAt:Date.now(),elapsed:0,limit:+minutes*60,finished:false};state.attempts.push(a);save();go('/attempt/'+a.id);}
function capture(){let a=activeAttempt();if(a&&!a.finished&&currentStart!==null){let now=Date.now();let delta=Math.max(0,(now-currentStart)/1000);a.times=recordTime(a.times,a.index,currentStart,now);a.elapsed+=delta;currentStart=now;save();}}
function quizScreen(a){if(!a)return page(top('Quiz not found')+'<p>Return to Quiz to start a new attempt.</p>',{parent:'/quiz'});if(a.finished){go('/result/'+a.id);return '';}let s=subject(a.subject),q=a.questions[a.index];return `<div class="app-shell quiz-shell"><main><header class="quiz-header"><span>${s.name}</span><span class="timer">${icon('clock')}<b id="timer">${time(a.limit?Math.max(0,a.limit-a.elapsed):a.elapsed)}</b></span></header><div class="quiz-toolbar">${btn(icon('grid')+' Questions '+(navigatorOpen?'⌃':'⌄'),'navigator','button outline','aria-expanded="'+navigatorOpen+'"')}${btn('Exit','exit','button exit')}</div>${navigatorOpen?`<section class="question-dropdown card"><div class="section-heading"><h3>Jump to question</h3>${btn(icon('close'),'navigator','round','aria-label="Close question navigator"')}</div><div class="number-grid">${a.questions.map((_,i)=>btn(String(i+1)+(a.answers[i]!=null?'<small>✓</small>':''),'jump','number '+(a.answers[i]!=null?'answered ':'')+(a.index===i?'current':''),`data-index="${i}" aria-label="Question ${i+1}${a.answers[i]!=null?', answered':''}"`)).join('')}</div><p class="muted small">✓ Answered · Purple outline = current</p></section>`:''}<section class="card active-question"><div class="question-flow-bar"><span class="badge ${colors[(q.unit-1)%colors.length]}">Unit ${q.unit} · ${s.units[q.unit-1]?.title || 'Syllabus'}</span><span class="flow-type-badge">${a.type==='master' ? 'Master Mock · Q'+(a.index+1)+' of '+a.questions.length : 'BEU '+a.year+' Exam · Q'+(a.index+1)}</span></div><h1>${esc(q.text)}</h1><div class="options">${q.options.map((o,i)=>btn(`<span class="radio"></span><span>${esc(o)}</span>`,'answer','option '+(a.answers[a.index]===i?'chosen':''),`data-value="${i}" role="radio" aria-checked="${a.answers[a.index]===i}"`)).join('')}</div></section><span class="quiz-demo">${a.type==='master'?'Syllabus Practice · Unit '+q.unit:'BEU '+a.year+' Exam · Question '+(a.index+1)}</span></main><div class="quiz-dock">${btn(icon('back')+' Back','previous','back-pill',a.index===0?'disabled':'')}${btn(a.index===a.questions.length-1?'Submit '+icon('check'):'Next '+icon('arrow'),a.index===a.questions.length-1?'submit-quiz':'next','next-pill')}</div></div>`;}
function finish(a){capture();a.finished=true;a.finishedAt=Date.now();currentStart=null;save();go('/result/'+a.id);}
function resultPage(id){let a=state.attempts.find(a=>a.id===id);if(!a)return page(top('Result not found'),{parent:'/history'});let s=subject(a.subject),r=scoreQuiz(a.questions,a.answers,a.times),status=r.score>=80?'Strong performance':r.score>=60?'Making progress':'Needs revision';let unitStats={};a.questions.forEach((q,i)=>{let u=q.unit||1;if(!unitStats[u])unitStats[u]={total:0,correct:0,wrong:0,skipped:0};unitStats[u].total++;if(a.answers[i]==null)unitStats[u].skipped++;else if(a.answers[i]===q.answer)unitStats[u].correct++;else unitStats[u].wrong++;});let masteryHtml=`<section class="card unit-mastery-card"><h2>Unit-Wise Concept Mastery</h2><p class="muted small">Analyze topic retention and identify high-yield areas for focused revision.</p><div class="unit-mastery-list">${Object.keys(unitStats).sort((x,y)=>+x-+y).map(u=>{let st=unitStats[u],pct=Math.round((st.correct/st.total)*100);let uTitle=s.units[u-1]?.title||'Unit '+u;let tagClass=pct>=80?'green':pct>=50?'orange':'coral';let tagText=pct>=80?'Mastered':pct>=50?'Needs Practice':'Critical Revision';return `<div class="unit-mastery-row"><div class="unit-mastery-meta"><span class="badge ${colors[(u-1)%colors.length]}">Unit ${u}</span><b>${esc(uTitle)}</b><span class="badge ${tagClass}">${tagText} · ${pct}%</span></div>${bar(pct,colors[(u-1)%colors.length])}<div class="flow-meta"><span>${st.correct} of ${st.total} correct (${st.wrong} wrong, ${st.skipped} skipped)</span>${pct<70?`<span class="revision-tip">Review: ${esc(unitWeightage[s.id]?.find(w=>w.unit===+u)?.flow?.split('→')[0]?.trim()||'Key definitions')}</span>`:''}</div></div>`;}).join('')}</div></section>`;return page(`${top('Quiz Results',s.name+' · '+(a.type==='master'?'Syllabus Master Quiz':a.year+' PYQ Paper Quiz'))}<section class="hero purple result-hero"><div><span class="eyebrow">QUIZ COMPLETED</span><h1>${r.correct} / ${r.total}</h1><h2>${r.score}% score</h2><span class="badge ${r.score>=80?'green':'coral'}">${status}</span><p>Every review is a step forward.</p></div><img class="result-art" src="./assets/quiz.png" alt="Quiz trophy"></section><div class="stat-grid"><div class="stat mint"><b>${r.correct}</b><span>Correct</span></div><div class="stat rose"><b>${r.wrong}</b><span>Wrong</span></div><div class="stat cream"><b>${r.skipped}</b><span>Skipped</span></div></div><section class="card"><h2>Time summary</h2><div class="two-stats"><div><p>Total active time</p><b>${time(r.totalSeconds)}</b></div><div><p>Average per question</p><b>${time(r.totalSeconds/r.total)}</b></div></div><p class="muted small">Includes revisits. Time away from the app is excluded.</p></section><section class="card"><h2>Performance snapshot</h2><div class="two-stats"><div><p>Attempt accuracy</p><b>${r.accuracy}%</b>${bar(r.accuracy,'purple')}</div><div><p>Completion</p><b>${Math.round(r.attempted/r.total*100)}%</b>${bar(r.attempted/r.total*100,'teal')}</div></div><p class="muted small">Status uses score: 80%+ strong, 60–79% making progress, below 60% needs revision. Speed alone does not determine performance.</p></section>${masteryHtml}<div class="section-heading"><h2>Question-by-question review</h2></div><div class="chips">${[['all',`All (${r.total})`],['correct',`Correct (${r.correct})`],['wrong',`Wrong (${r.wrong})`],['skipped',`Skipped (${r.skipped})`]].map(([v,t])=>btn(t,'result-filter','chip '+(resultFilter===v?'selected purple-button':''),`data-value="${v}"`)).join('')}</div><div id="reviews">${a.questions.map((q,i)=>{let status=a.answers[i]==null?'skipped':a.answers[i]===q.answer?'correct':'wrong';if(resultFilter!=='all'&&resultFilter!==status)return '';return `<article class="card review"><div class="review-meta"><span class="badge purple">Q${i+1}</span><span class="badge ${status==='correct'?'green':status==='wrong'?'coral':'orange'}">${status}</span><span class="time-chip">${icon('clock')}${time(a.times[i])}</span></div><h3>${esc(q.text)}</h3><div class="answer-review"><div class="${status==='correct'?'mint':status==='wrong'?'rose':'cream'}"><small>Your answer</small><b>${a.answers[i]==null?'Not answered':esc(q.options[a.answers[i]])}</b></div><div class="mint"><small>Correct answer</small><b>${esc(q.options[q.answer])}</b></div></div><p class="explanation"><b>Explanation:</b> ${esc(q.explanation)}</p></article>`;}).join('')}</div><div class="action-row">${btn('Save & return to quizzes','save-result','button purple-button',`data-id="${a.id}"`)}${btn('Retry quiz','retry','button outline',`data-id="${a.id}"`)}</div>`,{parent:`/quiz/${a.type}/${a.subject}`});}
function taskRow(t){return `<div class="task-row"><input aria-label="Mark ${esc(t.title)} complete" type="checkbox" data-task="${t.id}" ${t.status==='done'?'checked':''}><div><h3>${esc(t.title)}</h3><p>${subject(t.subject).short} · ${t.minutes} min · ${formatDate(t.date)}</p></div>${t.status==='done'?'<span class="badge green">Done</span>':btn(icon('close'),'miss-task','round',`data-id="${t.id}" aria-label="Mark task missed"`)}</div>`;}
function planner(){let tasks=state.tasks.filter(t=>planFilter==='all'||(planFilter==='today'?t.date===dateKey():t.status==='missed'));return page(`${top('Preparation Planner','Small plans. Steady progress.')}${hero('MAKE TIME FOR WHAT MATTERS','Your path to exam day.','Plan a little. Learn a little. Every day.','blue')}<section class="card"><div class="section-heading"><h2>Exam schedule</h2></div><p class="small muted schedule-meta">All papers · ${examSession.label} IST</p><ol class="exam-schedule">${examSchedule.map(e=>{let sub=subject(e.subject),past=e.date<dateKey();return `<li class="exam-schedule-row"><span class="schedule-date ${sub.color}"><b>${new Date(e.date+'T12:00:00').getDate()}</b><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</small></span><div><span class="badge ${sub.color}">${sub.short}</span><h3>${sub.name}</h3><p><time datetime="${e.date}">${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short',year:'numeric'})}</time>${past?' · Completed':e.date===dateKey()?' · Today':''}</p></div></li>`;}).join('')}</ol><a href="${examSession.source}" class="text-link" target="_blank" rel="noopener">View official routine ${icon('arrow')}</a></section><section class="card"><h2>Your study plan</h2><p>Build 30-minute topic sessions around your availability and nearest exams.</p><div class="action-row">${btn('Build / refresh plan','generate-plan','button primary')}${link('Study preferences','/preferences','button outline')}</div><label class="toggle-row">Automatically reschedule pending work<input type="checkbox" id="auto-plan" ${state.settings.autoPlan?'checked':''}></label><p class="small muted">Completed tasks stay in your history. Missed tasks can be rescheduled.</p></section><form id="task-form" class="card form-card"><h2>Add a study task</h2><label>Task<input name="title" required maxlength="180" placeholder="e.g. Revise subnetting"></label><div class="form-grid"><label>Subject<select name="subject">${subjects.map(s=>`<option value="${s.id}">${s.short}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${dateKey()}"></label></div><button class="outline full">Add task</button></form><div class="chips">${[['today','Today'],['all','All tasks'],['missed','Missed']].map(([v,t])=>btn(t,'plan-filter','chip '+(planFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><section class="card task-list">${tasks.map(taskRow).join('')||'<div class="empty"><h3>Your plan is clear.</h3><p>Add a task or generate a study plan.</p></div>'}</section>`,{parent:'/home'});}
function regenerate(){let used=new Set(state.tasks.filter(t=>t.status==='done'||!t.auto).map(t=>t.topic));state.tasks=state.tasks.filter(t=>t.status==='done'||!t.auto);state.tasks.push(...buildPlan(allTopics.filter(t=>!used.has(t.id)),state.topics,dateKey(),state.settings.availability,examDates));save();}
function profileFooter(){const socialIcons={website:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18Z"/>',linkedin:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7.5 10v7M7.5 7v.1M11 17v-7m0 3a3 3 0 0 1 6 0v4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>'};return `<footer class="profile-footer"><h2 id="follow-heading">Follow us on</h2><nav class="social-links" aria-labelledby="follow-heading">${[['website','Website'],['linkedin','LinkedIn'],['mail','Mail']].map(([id,label])=>{const content=`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${socialIcons[id]}</svg><span>${label}</span>`;return socialLinks[id]?`<a class="social-link" href="${esc(socialLinks[id])}" ${id!=='mail'?'target="_blank" rel="noopener noreferrer"':''}>${content}</a>`:`<button class="social-link" type="button" disabled aria-label="${label} — coming soon">${content}</button>`;}).join('')}</nav><p class="app-version" title="Build ${esc(buildId)}">v${esc(appVersion)}</p><div class="brand-signature"><p class="brand-shimmer">BEU Exam Dost</p><p class="brand-shimmer brand-byline">By BEU Developer</p></div></footer>`;}
function isPwaActive(){try{return(typeof window!=='undefined'&&(window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true||document.referrer.includes('android-app://')));}catch{return false;}}
function showDesktopInstall(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(choice=>{if(choice?.outcome==='accepted')toast('BEU Exam Dost is being installed on this desktop.');installPrompt=null;});return;}dialog('Add BEU Exam Dost to your desktop','In Chrome or Edge, open the browser menu and choose “Install BEU Exam Dost” or “Apps → Install this site as an app.” The exact wording depends on your browser.',btn('Got it','cancel','button primary'));}
async function promptInstalledDesktopApp(){if(isPwaActive()||['Android','iOS'].includes(getDeviceInfo().os)||!navigator.getInstalledRelatedApps||sessionStorage.getItem('exam-dost-installed-prompt-seen'))return;try{const apps=await navigator.getInstalledRelatedApps();if(!apps.some(app=>app.platform==='webapp'))return;sessionStorage.setItem('exam-dost-installed-prompt-seen','true');dialog('BEU Exam Dost is installed','Open BEU Exam Dost from your desktop shortcut, Start menu, or home screen. You can continue in this browser instead.',btn('Continue in browser','installed-continue','button outline')+btn('I’ll open the installed app','installed-manual','button primary'));}catch{}}
function showInstallSheet(){if(isPwaActive()){toast('You are already using the BEU Exam Dost PWA app!');return;}const existing=document.getElementById('install-sheet-wrap');if(existing)existing.remove();const wrap=document.createElement('div');wrap.id='install-sheet-wrap';wrap.className='install-sheet-backdrop active';wrap.innerHTML=`<div class="install-bottom-sheet"><div class="sheet-drag-handle"></div><div class="sheet-header"><img src="./assets/icon-192.png" alt="BEU Exam Dost"><div><h3>Install BEU Exam Dost</h3><p>Instant Offline Study Companion · Free PWA</p></div></div><div class="sheet-steps"><div class="sheet-step"><span class="sheet-step-badge">1</span><div><strong>Fast 1-Tap Offline Access:</strong> All syllabus topics, 7-mark PYQs, and exam schedule stay saved on your device.</div></div><div class="sheet-step"><span class="sheet-step-badge">2</span><div><strong>On Android (Chrome / Brave / Edge):</strong> Tap “Install App Now” below or tap browser menu (⋮) → “Add to Home screen”.</div></div><div class="sheet-step"><span class="sheet-step-badge">3</span><div><strong>On iPhone (Safari):</strong> Tap the Share button [↑] at the bottom bar → scroll and tap “Add to Home Screen”.</div></div></div><div class="sheet-actions"><button class="primary full" id="sheet-install-action">Install App Now ${icon('download')}</button><button class="outline full" id="sheet-dismiss-action">Maybe Later</button></div></div>`;document.body.appendChild(wrap);wrap.querySelector('#sheet-dismiss-action').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove();};wrap.querySelector('#sheet-install-action').onclick=()=>{if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(c=>{if(c&&c.outcome==='accepted'){localStorage.setItem('pwa_installed','true');toast('✓ BEU Exam Dost PWA installing!');wrap.remove();render();}installPrompt=null;});}else{toast('Tap your browser menu (⋮ or Share) and select “Add to Home screen”.');}};}
function checkDesktopNotice(){}
function currentDeviceLabel(){const platform=navigator.userAgentData?.platform||navigator.platform||'';if(/android/i.test(platform)||/android/i.test(navigator.userAgent))return 'Android device';if(/iphone|ipad/i.test(platform)||/iphone|ipad/i.test(navigator.userAgent))return 'Apple mobile device';return 'Desktop browser';}
function renderSyncSettingsSection(){const meta=syncClient.metadata(),linked=!!meta?.credential,mobile=['Android','iOS'].includes(getDeviceInfo().os),pending=mobile?syncClient.phonePairing():null;const phone=pending&&pending.expiresAt>Date.now()?`<div class="phone-pairing-panel" id="phone-pairing-panel"><p>Your desktop PIN</p><strong>${esc(pending.code)}</strong><p id="phone-pairing-status">${pending.claimed?'Desktop requested access. Approve to continue.':'Waiting for the desktop to enter this PIN.'}</p><span>Expires in <span id="phone-pairing-countdown">${countdownLabel(pending.expiresAt)}</span></span>${pending.claimed?btn('Approve desktop','sync-phone-approve','button primary'):''}${btn('Cancel PIN','sync-phone-cancel','button danger')}</div>`:'';return `<section class="card settings-list sync-settings"><div class="sync-heading"><div><h2>${mobile?'Linked devices':'Desktop connection'}</h2><p>${mobile?'Keep your study profile available on devices you approve.':linked?'This desktop is linked to your primary BEU Exam Dost app.':'Connect this desktop to your primary BEU Exam Dost app to load your profile.'}</p></div>${linked?`<div class="sync-status-column"><span class="badge green" id="sync-status">Connected</span><small class="sync-last-sync" id="sync-last-sync">${syncLastSyncLabel(meta?.lastSyncedAt)}</small></div>`:`<span class="badge">${mobile?'Setting up':'Local only'}</span>`}</div>${linked?mobile?`<div class="sync-actions">${btn('Sync now','sync-now','button outline')}${btn('Scan desktop QR','sync-scan','button primary')}${btn('Generate desktop PIN','sync-phone-pin','button outline')}${btn('Manage devices','sync-devices','button outline')}</div>${phone}<p class="small muted">Your primary app controls linked devices. Study data is encrypted before sync.</p>`:`<div class="sync-actions">${btn('Log out of this desktop','sync-logout','button danger')}</div><p class="small muted">To manage or revoke connected devices, use Linked devices in your primary app.</p>`:mobile?`<p>Encrypted sync is enabled automatically when you create your profile.</p><div class="sync-actions">${btn('Retry sync setup','sync-auto-enroll','button primary')}</div>${phone}`:`<div class="sync-actions">${btn('Connect existing profile','sync-link-account','button primary')}</div><p class="small muted">Connect this desktop to your primary BEU Exam Dost app to load your profile.</p>`}</section>`;}
function syncSettingsSection(){const mobile=['Android','iOS'].includes(getDeviceInfo().os);let html=renderSyncSettingsSection().replace(`<div class="sync-actions">${btn('Log out of this desktop','sync-logout','button danger')}</div>`, '');return html.replace('</section>',`<div class="sync-actions profile-logout-action">${btn(mobile?'Log out and erase profile':'Log out of this desktop','profile-logout','button danger')}</div></section>`);}
function profile(){let p=percent(allTopics),done=state.attempts.filter(a=>a.finished),avg=done.length?Math.round(done.reduce((n,a)=>n+scoreQuiz(a.questions,a.answers,a.times).score,0)/done.length):0;let isPwa=isPwaActive(),device=getDeviceInfo(),desktop=!['Android','iOS'].includes(device.os);const appStatus=desktop&&!isPwa?`<section class="card settings-list desktop-install-card"><h2>Desktop app</h2><div class="settings-row"><span class="mini-icon orange">${icon('download')}</span><span><b>Add BEU Exam Dost to your desktop</b><small>Install it as a desktop app for a dedicated window and quick access.</small></span>${btn('Install desktop app','show-desktop-install','button primary')}</div></section>`:`<section class="card settings-list"><h2>PWA App Status</h2>${isPwa?`<div class="settings-row pwa-active-row"><span class="mini-icon green">${icon('check')}</span><span><b>Using BEU Exam Dost PWA App</b><small>Active on this device · Fast offline mode enabled</small></span><span class="badge green">PWA Active</span></div>`:`${row('Install BEU Exam Dost','Add the app to your home screen','/install','download','orange')}`}</section>`;const attempts=state.attempts.length?`<section class="card profile-quiz-history"><div class="section-heading"><h2>Recent quiz attempts</h2>${link('View all','/history','button outline')}</div>${[...state.attempts].sort((a,b)=>new Date(b.startedAt)-new Date(a.startedAt)).map(a=>{const s=subject(a.subject),r=a.finished?scoreQuiz(a.questions,a.answers,a.times):null;return link(`<div class="profile-attempt-heading"><span class="badge ${s.color}">${esc(s.short)}</span><b>${esc(a.type==='master'?'Master Quiz':a.year?`${a.year} PYQ Quiz`:'PYQ Quiz')}</b><span class="badge ${a.finished?(r.score>=80?'green':r.score>=60?'orange':'coral'):'orange'}">${a.finished?`${r.score}% · ${r.score>=80?'Strong performance':r.score>=60?'Making progress':'Needs revision'}`:'In progress'}</span></div><p>${a.finished?`${r.correct} correct · ${r.wrong} wrong · ${r.skipped} skipped · ${time(r.totalSeconds)} active time`:`${a.answers.filter(v=>v!=null).length} of ${a.questions.length} answered · Resume when ready`}</p><small>${new Date(a.startedAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}</small>${icon('chevron')}`,(a.finished?'/result/':'/attempt/')+a.id,'card history-card profile-attempt-card');}).join('')}</section>`:`<section class="card profile-quiz-history"><h2>Recent quiz attempts</h2><p class="muted">Your completed results and saved attempts will appear here.</p>${link('Explore quizzes','/quiz','button purple-button')}</section>`;return page(`${top('My Profile')}<section class="profile-hero lavender"><span class="avatar">${profileInitial()}</span><div><h1>${esc(state.profile.name)}</h1><p>${esc(state.profile.college)}</p><p>${esc(state.profile.branch)}</p><div class="chips"><span class="badge green">2024–28</span><span class="badge purple">Semester 4</span></div>${link('Edit profile','/edit-profile','button outline')}</div></section><div class="section-heading"><h2>Your preparation</h2></div><div class="stat-grid"><div class="stat mint"><b>${p.pct}%</b><span>Syllabus</span></div><div class="stat lavender"><b>${done.length}</b><span>Quizzes</span></div><div class="stat cream"><b>${avg}%</b><span>Avg. score</span></div></div>${attempts}<section class="card settings-list"><h2>Preferences</h2>${row('Study preferences','Daily availability & study goal','/preferences','settings','coral')}<div class="settings-row appearance-row">${icon('sun')}<span>Appearance</span><div class="theme-control"><span class="theme-label ${state.settings.theme==='light'?'is-selected':''}" aria-hidden="true">Light</span>${btn('<span class="theme-thumb"></span>','theme','theme-switch',`role="switch" aria-label="Dark mode" aria-checked="${state.settings.theme==='dark'}"`)}<span class="theme-label ${state.settings.theme==='dark'?'is-selected':''}" aria-hidden="true">Dark</span></div></div>${row('Study reminders','See today’s tasks in the app','/reminders','bell','green')}${row('Quiz history','Results & unfinished attempts','/history','clock','purple')}</section><section class="card settings-list"><h2>Help & Community</h2>${row('Help & Requests','Submit queries, solution requests or suggestions','/help','mail','coral')}${row('Updates & Notifications','In-app release changelog & alerts','/notifications','bell','purple')}</section><section class="card settings-list"><h2>Your data</h2>${btn(icon('upload')+'<span>Export backup</span>'+icon('chevron'),'export','settings-row')}${btn(icon('download')+'<span>Import backup</span>'+icon('chevron'),'import','settings-row')}</section>${syncSettingsSection()}${appStatus}<section class="card settings-list"><h2>About & Legal</h2>${row('About BEU Exam Dost','Mission, offerings & developer notes','/about','info','green')}${row('Privacy Policy','Data usage, local storage & AI disclaimer','/privacy','shield','purple')}${row('Terms & Conditions','Rules, liability & university disclaimer','/terms','document','blue')}</section>${profileFooter()}`,{parent:'/home'});}
function row(title,sub,path,ic,tone){return link(`<span class="mini-icon ${tone}">${icon(ic)}</span><span>${title}<small>${sub}</small></span>${icon('chevron')}`,path,'settings-row');}
function preferences(){return page(`${top('Study preferences','A routine that works for you')}<form id="preferences-form" class="card form-card"><h2>One primary goal</h2><label>My focus<select name="goal">${['Complete important topics','Revise the full syllabus','Improve MCQ accuracy','Focus on important PYQs'].map(g=>`<option ${state.settings.goal===g?'selected':''}>${g}</option>`).join('')}</select></label><h2>Daily availability</h2><p>Choose a separate study duration for every day.</p>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<label class="availability">${d}<select name="day${i}">${[0,30,60,90,120,180,240].map(n=>`<option value="${n}" ${+state.settings.availability[i]===n?'selected':''}>${n===0?'Day off':n+' minutes'}</option>`).join('')}</select></label>`).join('')}<label>Preferred study slot<select name="slot">${['Morning','Afternoon','Evening'].map(v=>`<option ${state.settings.slot===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary full">Save preferences</button></form>`,{parent:'/profile'});}
function historyPage(){return page(`${top('Quiz history','Your progress, one attempt at a time')}${state.attempts.length?[...state.attempts].reverse().map(a=>link(`<span class="subject-icon ${a.finished?'purple':'orange'}">${icon(a.finished?'trophy':'clock')}</span><div><h3>${subject(a.subject).short} · ${a.type==='master'?'Master Quiz':a.year+' Paper'}</h3><p>${a.finished?scoreQuiz(a.questions,a.answers,a.times).score+'% · Completed':'Saved · Resume attempt'}</p><small>${new Date(a.startedAt).toLocaleDateString('en-IN')}</small></div>${icon('chevron')}`,(a.finished?'/result/':'/attempt/')+a.id,'card history-card')).join(''):'<div class="card empty"><h2>Your first quiz is waiting.</h2><p>Completed results and saved attempts appear here.</p>'+link('Explore quizzes','/quiz','button purple-button')+'</div>'}`,{parent:'/profile'});}
function installPage(){let isPwa=isPwaActive();return page(`${top('Install BEU Exam Dost','Your study companion, one tap away')}${hero('TAKE YOUR STUDY WITH YOU','A little closer.<br>A little easier.','Choose how you want to use BEU Exam Dost.','blue','phone')}${isPwa?`<section class="card mode-card green"><span class="badge green">INSTALLED & ACTIVE</span><h2>Using the PWA App</h2><p>BEU Exam Dost is successfully running as an installed Progressive Web App on your device. All question papers, syllabus checklists, and exam schedules are cached locally.</p><div class="mode-features">✓ Fullscreen Experience · ✓ 100% Offline Ready · ✓ Zero App Store Needed</div></section>`:`<section class="card mode-card green"><span class="badge green">RECOMMENDED</span><h2>Install as PWA</h2><p>Add BEU Exam Dost to your home screen directly from your browser for instant offline access.</p><div class="mode-features">Offline study content · Fullscreen · No account needed</div>${btn('Download & Install PWA '+icon('download'),'show-install-sheet','button primary full')}`}<section class="card mode-card purple"><span class="badge green">AVAILABLE</span><h2>Android APK</h2><p>Download the standalone native Android APK package (9.5 MB) for direct installation.</p><a class="button outline full" href="/new-exam-dost.apk" download="new-exam-dost.apk">Download Android APK (9.5 MB)</a></section><div class="card notice">${icon('info')}<span>Open online once to ensure assets are fully cached offline. Installation is supported across Android Chrome, Samsung Internet, Edge, and iOS Safari.</span></div><p id="offline-status" class="footnote">${navigator.onLine?'You’re online':'You’re offline'}</p>`,{parent:'/profile'});}
function privacy(){return page(`${top('Privacy Policy','BEU Exam Dost')}<article class="card legal-document"><div class="legal-header"><span class="badge purple">LEGAL POLICY</span><h1>Privacy Policy</h1><p class="legal-meta"><strong>BEU Exam Dost</strong><br>By BEU Developer<br><strong>Last Updated:</strong> 25 October 2026</p></div><h2>1. About BEU Exam Dost</h2><p>BEU Exam Dost is an independent educational Progressive Web App (PWA) developed by BEU Developer to help Bihar Engineering University (BEU) students prepare for their examinations.</p><p>Our app provides previous-year questions (PYQs), study notes, AI-assisted solutions, practice tests, study planning, and progress tracking.</p><p>The app is created for educational assistance only.</p><h2>2. Information We Use</h2><p>To provide personalized features, BEU Exam Dost may use basic information such as:</p><ul><li>Name and academic details provided by students.</li><li>Selected subjects and study preferences.</li><li>Study plans, completed tasks, and learning progress.</li><li>Practice test scores and performance records.</li><li>Bookmarked questions and saved preferences.</li></ul><p>Some information may be stored in your browser to keep app features working properly.</p><div class="legal-alert"><p><strong>Optional device sync</strong></p><p>Sync is off by default. If you enable it, your profile and study data listed above are sent over a secure connection and stored in the BEU Exam Dost cloud database so devices you approve can share it. The account is anonymous and does not require an email address, phone number, password, or OTP.</p><p>Pairing codes expire quickly, and device credentials can be revoked. Revoking prevents future access but cannot erase data already downloaded to a device. You can delete the cloud copy from Linked devices; this does not delete the local copy on your current device.</p></div><p>We use this information to support your learning experience, not for selling personal data.</p><h2>3. AI-Generated Solutions</h2><div class="legal-alert"><p><strong>Important: Please read before using our study materials.</strong></p><p>Some answers, explanations, and solutions available on BEU Exam Dost are prepared with the assistance of Artificial Intelligence (AI).</p><p>While we aim to provide helpful and understandable solutions, AI can make mistakes.</p></div><p>Therefore:</p><ul><li>Some answers may contain incorrect information or calculations.</li><li>Explanations may occasionally be incomplete.</li><li>Solutions may differ from answers expected by university examiners.</li><li>We do not guarantee that every answer is 100% accurate.</li><li>Students should verify important answers using textbooks, teachers, and official study materials.</li></ul><p><strong>BEU Exam Dost and BEU Developer are not responsible for incorrect AI-generated answers or academic consequences resulting from relying on them, to the extent permitted by applicable law.</strong></p><h2>4. Previous-Year Questions and Study Materials</h2><p>We provide PYQs, notes, and other educational resources to help students prepare for examinations.</p><p>We try to keep these materials useful and relevant. However, we cannot guarantee that every question, solution, or document is completely accurate, updated, or free from errors.</p><p>Students should refer to official university announcements and resources for confirmed examination information.</p><h2>5. Study Planner and Progress Tracking</h2><p>BEU Exam Dost includes study planning and progress tracking features to help students organize their preparation.</p><p>Study schedules, suggestions, progress percentages, and preparation insights are intended as guidance only.</p><p>They do not guarantee specific marks, examination results, or academic success.</p><h2>6. Local Data and Optional Encrypted Sync</h2><p>By default, your profile, study progress, planner, saved questions and quiz history stay in this browser or installed app.</p><p>If you enable sync, the app encrypts your study snapshot on your device before sending it to Neon. The sync service stores ciphertext and device-management metadata; it does not receive the study-data encryption key. BEU Exam Dost on your primary device shares that key only after you approve pairing.</p><p>Pairing codes expire after three minutes and allow up to five attempts. Revoking a device blocks future sync; it cannot erase data while the device is offline or erase copies made outside the app. If every device holding the key is lost, the cloud copy cannot be recovered. You can delete the cloud sync copy from the app.</p><p>Profile setup and app-open events send the operating system and whether the app is installed or open in a browser to the BEU Exam Dost team for usage reporting. These events do not include your study progress. Help details are sent only when you submit a help request.</p><p>Clearing browser data, uninstalling the PWA, or changing devices may remove local information.</p><h2>7. External Links</h2><p>Our app may contain links to external educational resources and websites.</p><p>We are not responsible for the content, accuracy, or privacy practices of those external websites.</p><h2>8. Independent Educational Platform</h2><p>BEU Exam Dost is developed and managed independently by BEU Developer.</p><p><strong>It is not an official application of Bihar Engineering University (BEU), nor is it affiliated with or endorsed by the university.</strong></p><p>The university's name is used only to identify the academic context for which the app provides learning resources.</p><h2>9. Limitation of Responsibility</h2><p>BEU Exam Dost is provided as an educational support tool.</p><p>BEU Exam Dost and BEU Developer do not guarantee:</p><ul><li>Completely error-free answers or study materials.</li><li>Any specific examination marks or results.</li><li>Uninterrupted app availability.</li><li>Complete accuracy of AI-generated explanations.</li><li>Recovery of locally deleted app data.</li></ul><p>Users are responsible for independently verifying academic information before relying on it.</p><p>To the extent permitted by applicable law, BEU Exam Dost and BEU Developer are not liable for academic losses or other consequences resulting from inaccurate study content or technical issues.</p><h2>10. Updates to This Policy</h2><p>We may update this Privacy Policy when BEU Exam Dost features or practices change.</p><p>The updated version will be published within the application.</p><h2>11. Contact</h2><p>For questions, feedback, or reporting incorrect content, users may contact BEU Developer through the official contact channel provided in the app.</p><div class="legal-footer"><p><strong>Disclaimer:</strong> BEU Exam Dost is an independent educational project. AI-assisted solutions may contain mistakes. Always verify answers before using them for examination preparation.</p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function about(){return page(`${top('About BEU Exam Dost','Your Exam Companion')}<article class="card legal-document"><div class="legal-header"><span class="badge green">ABOUT US</span><h1>About BEU Exam Dost</h1><p class="legal-tagline"><strong>Your Companion for BEU Exam Success</strong></p></div><p><strong>BEU Exam Dost</strong> is an independent educational Progressive Web App (PWA), developed by <strong>BEU Developer</strong>, to make examination preparation easier, more organized, and accessible for students of Bihar Engineering University (BEU).</p><p>We understand that students often need to manage multiple subjects, find previous-year questions, prepare reliable notes, and complete their syllabus within limited time.</p><p>BEU Exam Dost brings useful preparation resources and study tools together in one place.</p><h2>What We Offer</h2><h3>Previous-Year Questions (PYQs)</h3><p>Explore previous-year examination questions to understand question patterns, important topics, and examination requirements.</p><h3>AI-Assisted Solutions</h3><p>Access detailed explanations and solutions prepared with the assistance of Artificial Intelligence to support learning and revision.</p><h3>Subject-Wise Preparation</h3><p>Organize preparation through subjects, units, topics, and relevant educational resources.</p><h3>Smart Study Planner</h3><p>Create and manage personalized study schedules, daily tasks, and preparation goals.</p><h3>Practice Tests</h3><p>Evaluate understanding through practice questions and tests designed for examination preparation.</p><h3>Progress Tracking</h3><p>Monitor completed tasks, preparation progress, and practice performance to identify areas that need more attention.</p><h2>Our Mission</h2><p>Our mission is simple:</p><p style="font-size:16px;font-weight:600;color:var(--forest,#15864c)">“To make BEU examination preparation more accessible, structured, and less stressful for students.”</p><p>We aim to help students spend less time searching for study resources and more time understanding concepts, practicing questions, and preparing confidently.</p><h2>Built for Students</h2><p>BEU Exam Dost is designed with the everyday needs of engineering students in mind.</p><p>Whether you are revising a unit, solving previous-year questions, or planning your next study session, the app aims to make your preparation more manageable.</p><h2>Important Note</h2><p>Some solutions and explanations are created using AI and may contain mistakes. Students should verify important academic information using textbooks, teachers, and official university resources.</p><p><strong>BEU Exam Dost is an independent educational project and is not an official application of, affiliated with, or endorsed by Bihar Engineering University.</strong></p><div class="legal-footer"><p><strong>BEU Exam Dost</strong><br><em>Same Notes. Same Dreams. Stronger Together.</em><br>Developed by <strong>BEU Developer</strong></p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function terms(){return page(`${top('Terms & Conditions','User Agreement')}<article class="card legal-document"><div class="legal-header"><span class="badge blue">TERMS & CONDITIONS</span><h1>Terms & Conditions</h1><p class="legal-meta"><strong>BEU Exam Dost — By BEU Developer</strong><br><strong>Last Updated:</strong> 23 October 2026</p></div><p>Welcome to BEU Exam Dost. These Terms & Conditions explain the basic rules and limitations of using our educational application.</p><p>By using BEU Exam Dost, you agree to these terms.</p><h2>1. Purpose of the App</h2><p>BEU Exam Dost is an independent educational platform designed to help Bihar Engineering University students with examination preparation.</p><p>The app provides previous-year questions, study notes, AI-assisted solutions, practice tests, study planning, and progress tracking.</p><p>All resources are intended for educational and personal study purposes.</p><h2>2. AI-Generated Solutions and Accuracy</h2><div class="legal-alert"><p><strong>Important Disclaimer</strong></p><p>Some answers, explanations, and educational solutions available on BEU Exam Dost are prepared using Artificial Intelligence (AI).</p><p>AI-generated content may contain mistakes, including incorrect calculations, incomplete explanations, or inaccurate information.</p></div><p>Please understand that:</p><ul><li>We do not guarantee 100% accuracy of AI-assisted solutions.</li><li>Answers may differ from university-approved or examiner-expected solutions.</li><li>Some educational information may be incomplete or outdated.</li><li>Students should verify important answers using textbooks, teachers, or official resources.</li></ul><p><strong>BEU Exam Dost and BEU Developer are not responsible for incorrect AI-generated solutions or resulting academic consequences, including loss of marks or examination performance, to the extent permitted by applicable law.</strong></p><p>Students use these solutions at their own discretion.</p><h2>3. Previous-Year Questions and Study Materials</h2><p>Previous-year questions, notes, and other study materials are provided to assist examination preparation.</p><p>We try to present relevant information, but we cannot guarantee that every question, document, or solution is completely accurate or up to date.</p><p>BEU Exam Dost does not guarantee that any particular question will appear in an upcoming examination.</p><p>For confirmed syllabi, exam schedules, results, and official announcements, students should refer to Bihar Engineering University's official communications.</p><h2>4. Study Planner and Practice Tests</h2><p>The study planner, preparation percentages, practice scores, and learning recommendations are designed to help students organize their studies.</p><p>These features provide estimates and guidance based on available information and user activity.</p><p>They do not guarantee examination success, passing marks, or any specific academic result.</p><h2>5. Responsible Use</h2><p>Users are expected to use BEU Exam Dost for legitimate educational purposes.</p><p>Users should not:</p><ul><li>Attempt to damage, disrupt, or misuse the application.</li><li>Access other users' accounts or information without permission.</li><li>Submit harmful or abusive content through app features.</li><li>Misrepresent BEU Exam Dost as an official university service.</li></ul><p>We may restrict access to features where reasonably necessary to prevent misuse.</p><h2>6. Educational Content and Ownership</h2><p>BEU Exam Dost may contain educational materials, previous-year questions, explanatory content, and references to third-party resources.</p><p>Original app design, branding, and developer-created content belong to BEU Developer, except where otherwise stated.</p><p>University names, trademarks, and third-party materials belong to their respective owners.</p><p>Users may use available study resources for personal educational purposes, subject to any applicable third-party rights.</p><h2>7. App Availability and Saved Data</h2><p>We aim to keep BEU Exam Dost accessible and functional, but temporary errors, maintenance, or technical interruptions may occur.</p><p>Certain preferences and learning information may be stored locally in the user's browser.</p><p>Clearing browser storage, uninstalling the PWA, or changing devices may result in loss of locally saved or unsynchronized information.</p><p>We cannot guarantee uninterrupted availability or recovery of deleted local data.</p><h2>8. No Official University Affiliation</h2><p><strong>BEU Exam Dost is not an official application of Bihar Engineering University.</strong></p><p>It is independently developed and maintained by BEU Developer.</p><p>The application is not affiliated with, authorized by, or endorsed by Bihar Engineering University.</p><p>References to BEU, academic subjects, and examinations are provided for educational identification purposes only.</p><h2>9. Limitation of Liability</h2><p>BEU Exam Dost is provided as an educational assistance tool.</p><p>We make reasonable efforts to provide useful learning resources, but we do not guarantee that all content and features will be accurate, complete, or error-free.</p><p>To the maximum extent permitted by applicable law, BEU Exam Dost and BEU Developer will not be liable for academic losses, incorrect answers, examination results, or other consequences resulting from reliance on educational content or app technical issues.</p><p>Nothing in these Terms excludes rights or responsibilities that cannot legally be excluded.</p><h2>10. Changes to the App and Terms</h2><p>We may update, improve, modify, or discontinue app features as the project develops.</p><p>These Terms & Conditions may also be updated when necessary.</p><p>The latest version will be made available within the application, with its updated revision date.</p><h2>11. Privacy</h2><p>Information about how BEU Exam Dost handles user information and app storage is available in our separate <strong>Privacy Policy</strong>.</p><p>Users are encouraged to read that policy to understand the application's data practices.</p><h2>12. Contact and Feedback</h2><p>If you find an incorrect solution, broken feature, or other issue, you can report it through the official contact or feedback channel provided within BEU Exam Dost.</p><p>We welcome constructive suggestions that help improve the platform.</p><div class="legal-footer"><p><strong>Final Disclaimer:</strong> BEU Exam Dost is an independent educational assistance platform. AI-generated solutions may contain errors. Students are responsible for verifying academic information before relying on it. BEU Exam Dost and BEU Developer do not guarantee examination results and disclaim responsibility for inaccuracies and their consequences to the extent permitted by applicable law.</p><p><strong>BEU Exam Dost</strong><br>Developed by <strong>BEU Developer</strong></p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function reminders(){let t=state.tasks.filter(t=>t.date<=dateKey()&&t.status==='pending');return page(`${top('Study reminders','Your next small step')}<div class="card notice">${icon('bell')}<span>In-app reminders only. Background push notifications are not connected.</span></div><section class="card task-list">${t.map(taskRow).join('')||'<div class="empty">You’re all caught up. Add your next task in the planner.</div>'}</section>${link('Open planner','/planner','button primary')}`,{parent:'/home'});}
function formatDate(v){return new Date(v+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}function time(n){n=Math.max(0,Math.floor(n||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function notificationsPage(){const d=dismissedIds();const visible=sortNotifications(changelog).filter(c=>!d.has(c.id));return page(`${top('Updates & Notifications','In-App Changelog')}<section class="card summary mint"><div><h2>What’s New in BEU Exam Dost</h2><p>Stay informed with newly added model solutions, question banks, and app features.</p></div>${icon('bell')}</section><div class="section-heading"><h2>Recent Updates (${visible.length})</h2>${visible.length?btn('Clear all','clear-all-notifs','text-link'):''}</div><div class="notif-list">${visible.map(c=>`<article class="card notif-card ${notifTypeTone(c.type)}" id="notif-${c.id}"><div class="notif-header"><span class="badge ${notifTypeTone(c.type)}">${esc(c.badge||c.type)}</span><time class="notif-time" datetime="${esc(c.date)}" title="${c.historical?'Release recorded in Git history':'Issued'}">${formatNotifDate(c.date)}</time>${btn(icon('close'),'dismiss-notif','round notif-close',`data-id="${c.id}" aria-label="Dismiss notification"`)}</div><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p></article>`).join('')||`<div class="card empty"><span class="subject-icon green">${icon('check')}</span><h3>You’re All Caught Up!</h3><p>No new notifications at this time. Check back soon for new subject PYQs and solutions.</p></div>`}</div>`,{parent:'/home'});}
function helpPage(){return page(`${top('Help & Requests','Submit queries, solution requests or suggestions')}<form id="help-form" class="card form-card"><h2>Submit a Request or Query</h2><p class="muted small">Need an answer to a specific BEU question, want to report an issue, or suggest a new feature? Send a request to our support team.</p><label>Your Name<input name="name" required maxlength="100" placeholder="Your name" value="${esc(state.profile?.name||'')}"></label><label>College<input name="college" required maxlength="120" placeholder="Your college" value="${esc(state.profile?.college||'')}"></label><label>Category<select name="category" required><option value="PYQ / Solution Request">📚 PYQ / Model Solution Request</option><option value="Report Content Error">⚠️ Report an Error in Question/Answer</option><option value="Feature Suggestion">💡 App Feature Suggestion</option><option value="General Query">❓ General Query / Academic Help</option></select></label><label>Related Subject (Optional)<select name="subject"><option value="">General / All Subjects</option>${subjects.map(s=>`<option value="${esc(s.name)}">${esc(s.name)} (${s.short})</option>`).join('')}</select></label><label>Your Message / Query<textarea name="message" required rows="4" maxlength="1500" placeholder="Describe your question, request, or suggestion in detail..."></textarea></label><button class="primary full" id="help-submit-btn">Send request ${icon('arrow')}</button></form><div class="card notice">${icon('info')}<span>Your name, college, branch and request details are sent to the BEU Exam Dost support team via Telegram when you submit.</span></div>`,{parent:'/profile'});}
function render(){let r=route();document.documentElement.dataset.theme=state.settings.theme;checkDesktopNotice();if(r[0]==='quiz'&&!r[1]&&matchMedia('(min-width: 861px)').matches){location.replace('#/quiz/pyq');return;}let html;if(r[0]==='welcome')html=desktopWelcomePage();else if(r[0]==='sync-login')html=syncLoginPage();else if(r[0]==='create-account')html=createAccountPage();else if(!state.profile&&!['privacy','about','terms'].includes(r[0]))html=!['Android','iOS'].includes(getDeviceInfo().os)&&!r[0]?desktopWelcomePage():setup();else switch(r[0]){case 'setup':html=state.profile?home():setup();break;case 'edit-profile':html=setup(true);break;case 'subjects':html=r[2]?unitPage(r[1],r[2]):r[1]?subjectPage(r[1]):subjectsPage();break;case 'pyqs':html=r[1]?pyqSubject(r[1]):pyqIndex();break;case 'quiz':html=r[2]?quizSets(r[1],r[2]):r[1]?quizSubjects(r[1]):quizIndex();break;case 'attempt':html=quizScreen(activeAttempt());break;case 'result':html=resultPage(r[1]);break;case 'planner':html=planner();break;case 'profile':html=profile();break;case 'link-device':html=profile();break;case 'preferences':html=preferences();break;case 'history':html=historyPage();break;case 'install':html=installPage();break;case 'privacy':html=privacy();break;case 'about':html=about();break;case 'terms':html=terms();break;case 'reminders':html=reminders();break;case 'notifications':html=notificationsPage();break;case 'help':html=helpPage();break;default:html=home();}$('#app').innerHTML=html;$('#app').classList.remove('app-booting');if(r[0]==='sync-login')restorePendingPairing();if(r[0]==='profile')startPhonePairingPolling();else stopPhonePairingTimer();if(r[0]==='link-device')handleIncomingPairRoute();const titles={welcome:'BEU Exam Dost · Desktop', 'sync-login':'Sync login · BEU Exam Dost','create-account':'Create account · BEU Exam Dost',privacy:'Privacy Policy · BEU Exam Dost',about:'About BEU Exam Dost · BEU Developer',terms:'Terms & Conditions · BEU Exam Dost',install:'Install BEU Exam Dost PWA',planner:'BEU 4th Sem Exam Routine & Routine Tracker · BEU Exam Dost',profile:'My Profile · BEU Exam Dost',history:'Quiz Performance History · BEU Exam Dost',preferences:'Study Preferences · BEU Exam Dost',reminders:'Study Reminders · BEU Exam Dost',notifications:'Updates & Notifications · BEU Exam Dost',help:'Help & Requests · BEU Exam Dost'};if(r[0]==='subjects')document.title=(r[1]?subject(r[1]).name+(r[2]?' Unit '+r[2]:'')+' Syllabus & Notes':'BEU 4th Sem CSE Subjects & Notes')+' · BEU Exam Dost';else if(r[0]==='pyqs')document.title=(r[1]?subject(r[1]).name+' PYQ & 7-Mark Questions':'BEU 4th Sem CSE PYQ Question Banks')+' · BEU Exam Dost';else if(r[0]==='quiz')document.title=(r[2]?subject(r[2]).name+' Objective MCQ Quiz':'BEU 4th Sem CSE Practice Quizzes & MCQs')+' · BEU Exam Dost';else if(titles[r[0]])document.title=titles[r[0]];else document.title='BEU 4th Sem CSE PYQ, Notes, Syllabus | BEU Exam Dost';announceNewNotifications();updateSyncStatus();}
function dialog(title,body,actions){let m=$('#modal');m.classList.remove('sync-modal');m.innerHTML=`<div class="dialog-inner"><h2>${title}</h2><p>${body}</p><div class="dialog-actions">${actions}</div></div>`;m.showModal();}
function contentDialog(title,content,actions){let m=$('#modal');m.classList.add('sync-modal');m.innerHTML=`<div class="dialog-inner sync-dialog-inner"><h2>${title}</h2><div class="sync-dialog-content">${content}</div><div class="dialog-actions">${actions}</div></div>`;m.showModal();}
function stopPairingTimer(){if(pairingTimer){clearInterval(pairingTimer);pairingTimer=null;}}
function stopPairScanner(){if(pairScanner){pairScanner.destroy();pairScanner=null;}}
function consentToSync(){contentDialog('Enable optional cloud sync?',`<p>Your profile and study data will be encrypted on this device before upload. Neon stores ciphertext; the app server cannot read the synced snapshot.</p><p>BEU Exam Dost on your primary device keeps the encryption key and shares it with a new device only after you approve pairing. If every device holding that key is lost, the encrypted cloud copy cannot be recovered. You can unlink this device or delete the cloud copy later.</p><p class="small muted">No email, phone number, password or OTP is required.</p>`,btn('Keep local only','cancel','button outline')+btn('I agree · Enable sync','sync-enroll-confirm','button primary'));}
async function enableSync(){closeDialog();try{await syncClient.enroll(state,currentDeviceLabel(),true);syncStatus='synced';render();toast('Sync enabled on this device. Your study data is now backed up.');if(incomingPairing)openPairApproval(incomingPairing);}catch(error){toast(error.message||'Could not enable sync. Your local data is unchanged.');}}
function pairReviewDialog(){const meta=syncClient.metadata();if(!meta?.pendingReview)return;persistSyncedState(meta.remoteSnapshot);meta.pendingReview=false;delete meta.remoteSnapshot;syncClient.saveMetadata(meta);go('/home');render();}
async function resolvePairing(){const meta=syncClient.metadata();if(!meta?.pendingReview)return;persistSyncedState(meta.remoteSnapshot);meta.pendingReview=false;delete meta.remoteSnapshot;syncClient.saveMetadata(meta);go('/home');render();}
function countdownLabel(until){const seconds=Math.max(0,Math.ceil((until-Date.now())/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function pairingCountdown(){return countdownLabel(pairingExpiresAt);}
function pairingRefreshUntil(){try{return Math.max(pairingRefreshAvailableAt,Number(localStorage.getItem(PAIRING_REFRESH_KEY))||0);}catch{return pairingRefreshAvailableAt;}}
function renderPairingDialog(pairing){pairingExpiresAt=Number(pairing.expiresAt);pairingStartLockedUntil=pairingExpiresAt;const slot=$('#pairing-qr-slot'),region=$('#pairing-status-region');if(!slot||!region)return;const code=QRCode(0,'M');code.addData(pairing.link);code.make();slot.innerHTML=`<div class="sync-qr">${code.createSvgTag(6,4)}</div>`;slot.classList.add('has-pairing-qr');region.innerHTML=`<h3>Approve this desktop</h3><p>Scan this QR code with BEU Exam Dost on your primary device.</p><p id="pairing-status" class="sync-pair-status"><span id="pairing-wait-label">Waiting for approval</span><span> · <span id="pairing-countdown">${pairingCountdown()}</span> remaining</span></p><p class="small muted">The pairing QR is valid for two minutes.</p><button class="button danger pairing-cancel" data-action="sync-cancel">Cancel pairing</button>`;stopPairingTimer();if(Date.now()>=pairingExpiresAt)expireDesktopPairing();else pairingTimer=setInterval(pollDesktopPairing,1000);}
function restorePendingPairing(){const pending=syncClient.pendingPairing();if(!pending||!Number.isFinite(Number(pending.expiresAt))||!pending.sessionId)return;pairingExpiresAt=Number(pending.expiresAt);pairingStartLockedUntil=pairingExpiresAt;if(pending.method==='pin'){stopPairingTimer();pairingTimer=setInterval(pollDesktopPairing,1000);return;}if(!pending.requestCredential||!pending.publicKey)return;renderPairingDialog({...pending,link:`${syncClient.origin}/#/link-device/${pending.sessionId}/${pending.requestCredential}/${pending.publicKey}`});}
async function openPairingQr(){const pending=syncClient.pendingPairing();if(pending&&Number.isFinite(Number(pending.expiresAt))){restorePendingPairing();return;}if(Date.now()<pairingStartLockedUntil){restorePendingPairing();return;}const refreshWait=pairingRefreshUntil()-Date.now();if(refreshWait>0){toast(`For security, a new QR will be available in ${countdownLabel(pairingRefreshUntil())}.`);return;}try{const pairing=await syncClient.beginPairing(currentDeviceLabel());pairingRefreshAvailableAt=0;try{localStorage.removeItem(PAIRING_REFRESH_KEY);}catch{}renderPairingDialog(pairing);}catch(error){toast(error.message||'Could not start device pairing.');}}
function updatePairingRefreshButton(){const button=$('#pairing-refresh-button');if(!button){stopPairingTimer();return;}const until=pairingRefreshUntil(),remaining=Math.max(0,Math.ceil((until-Date.now())/1000)),countdown=$('#pairing-refresh-countdown'),status=$('#pairing-status');button.disabled=remaining>0;if(countdown)countdown.textContent=countdownLabel(until);if(!remaining&&status)status.textContent='The secure refresh hold is complete. You can generate a new QR code.';}
function expireDesktopPairing(){const slot=$('#pairing-qr-slot'),status=$('#pairing-status-region');if(slot)slot.innerHTML='<span>QR expired</span>';const until=Math.max(pairingExpiresAt+10000,pairingRefreshUntil());pairingRefreshAvailableAt=until;try{localStorage.setItem(PAIRING_REFRESH_KEY,String(until));}catch{}syncClient.cancelPairing();if(status){status.innerHTML=`<p id="pairing-status" class="pairing-expired">This pairing expired. You can generate a new QR in <span id="pairing-refresh-countdown">${countdownLabel(until)}</span>.</p><button id="pairing-refresh-button" class="button primary pairing-refresh" data-action="sync-refresh-pairing">Generate new QR</button>`;}stopPairingTimer();updatePairingRefreshButton();if(pairingRefreshUntil()>Date.now())pairingTimer=setInterval(updatePairingRefreshButton,1000);}
async function pollDesktopPairing(){const pending=syncClient.pendingPairing(),el=$('#pairing-status');if(!pending){stopPairingTimer();return;}const timer=$('#pairing-countdown');if(timer)timer.textContent=pairingCountdown();if(Date.now()>=pairingExpiresAt){if(el)el.textContent='This pairing has expired. Start again from your primary device.';stopPairingTimer();syncClient.cancelPairing();return;}try{const status=await syncClient.pairingStatus();if(status.status==='expired'){stopPairingTimer();syncClient.cancelPairing();if(el)el.textContent='This pairing has expired.';return;}if(status.status==='approved'){stopPairingTimer();const result=await syncClient.completePairing();if(result.status==='approved'){persistSyncedState(result.snapshot);go('/home');render();toast('Your primary device data is ready on desktop.');}return;}const label=$('#pairing-wait-label');if(label)label.textContent=pending.method==='pin'?'Waiting for approval on your primary device':`Waiting for approval from ${status.deviceLabel||'your linked device'}`;}catch{}}
async function openPairApproval(pairing){incomingPairing=pairing;try{const status=await syncClient.checkPairing(pairing.sessionId,pairing.requestCredential);if(status.status!=='pending'||status.publicKey!==pairing.publicKey){toast('This pairing code is invalid, expired, or has already been used.');return;}contentDialog('Approve a new device?',`<p><b>${esc(status.deviceLabel||'New device')}</b> is requesting encrypted access to your profile and study progress.</p><p>Approve only if you started this pairing. You can revoke the device later in Linked devices.</p>`,btn('Not now','cancel','button outline')+btn('Approve device','sync-approve-device','button primary',`data-session="${esc(pairing.sessionId)}" data-request="${esc(pairing.requestCredential)}"`));}catch(error){toast(error.message||'Could not check this pairing request.');}}
async function approveIncomingPairing(sessionId,requestCredential){try{await syncClient.approvePairing(sessionId,requestCredential,incomingPairing?.publicKey);incomingPairing=null;handledPairing=`${sessionId}/${requestCredential}`;closeDialog();toast('Device approved. Its encrypted sync key was shared securely.');}catch(error){toast(error.message||'Could not approve this device.');}}
function onboardingPinCode(){return[...document.querySelectorAll('[data-pin-digit]')].map(input=>input.value.replace(/\D/g,'').slice(0,1)).join('');}
function openPairingCodeEntry(){contentDialog('Enter desktop pairing code',`<p>Enter the four-digit code displayed beside the QR code on your desktop.</p><label>Pairing code<input id="pair-code-input" inputmode="numeric" autocomplete="one-time-code" maxlength="4" pattern="[0-9]{4}" placeholder="0000"></label><p class="small muted">Codes expire after two minutes and allow up to five attempts.</p>`,btn('Cancel','sync-scanner-cancel','button outline')+btn('Approve connection','sync-code-submit','button primary'));}
async function submitPairingCode(codeOverride){const code=(codeOverride??onboardingPinCode()).replace(/\D/g,'');if(!/^\d{4}$/.test(code)){toast('Enter the four-digit PIN generated in BEU Exam Dost on your primary device.');return;}try{await syncClient.claimPairingCode(code,currentDeviceLabel());pairingExpiresAt=Number(syncClient.pendingPairing()?.expiresAt);syncLoginMode='pin';render();toast('PIN submitted. Approve this desktop in BEU Exam Dost on your primary device.');}catch(error){toast(error.message||'Could not submit this PIN.');}}
let phonePairingTimer=null;
function stopPhonePairingTimer(){if(phonePairingTimer){clearInterval(phonePairingTimer);phonePairingTimer=null;}}
async function autoEnableMobileSync(){if(!state.profile||!['Android','iOS'].includes(getDeviceInfo().os)||syncClient.metadata()?.credential)return;try{await syncClient.enroll(state,currentDeviceLabel(),true);syncStatus='synced';}catch(error){console.warn('Automatic encrypted sync setup pending:',error.message);}finally{if(route()[0]==='profile')render();}}
async function beginMobilePinPairing(){try{await syncClient.beginPhonePairing(currentDeviceLabel());render();startPhonePairingPolling();}catch(error){toast(error.message||'Could not create a desktop PIN.');}}
function startPhonePairingPolling(){stopPhonePairingTimer();const tick=async()=>{const pending=syncClient.phonePairing(),panel=$('#phone-pairing-panel');if(!pending||!panel){stopPhonePairingTimer();return;}const count=$('#phone-pairing-countdown');if(count)count.textContent=countdownLabel(pending.expiresAt);if(Date.now()>=pending.expiresAt){syncClient.cancelPhonePairing();render();stopPhonePairingTimer();return;}try{const status=await syncClient.phonePairingStatus();const label=$('#phone-pairing-status');if(label)label.textContent=status.status==='claimed'?`${status.deviceLabel||'A desktop'} entered the PIN. Approve to link it.`:'Waiting for the desktop to enter this PIN.';if(status.status==='claimed'&&!$('#sync-phone-approve'))label?.insertAdjacentHTML('afterend',`<button id="sync-phone-approve" class="button primary" data-action="sync-phone-approve">Approve desktop</button>`);}catch{}};tick();phonePairingTimer=setInterval(tick,1000);}
async function approvePhonePairing(){try{await syncClient.approvePhonePairing();stopPhonePairingTimer();render();toast('Desktop approved.');}catch(error){toast(error.message||'Could not approve this desktop.');}}
function showQrScanner(){contentDialog('Scan the desktop QR code',`<p>Scan the temporary QR code displayed by BEU Exam Dost on your desktop.</p><div class="sync-scanner"><video id="pair-scanner-video" muted playsinline></video></div><p id="pair-scan-error" class="small muted">Allow camera access to scan.</p>`,btn('Cancel','sync-scanner-cancel','button outline'));const video=$('#pair-scanner-video');pairScanner=new QrScanner(video,result=>{const pairing=parsePairingLink(result.data,location.origin);if(!pairing){$('#pair-scan-error').textContent='That QR code is not a BEU Exam Dost pairing code.';return;}stopPairScanner();closeDialog();openPairApproval(pairing);},{preferredCamera:'environment',returnDetailedScanResult:true});pairScanner.start().catch(()=>{const error=$('#pair-scan-error');if(error)error.textContent='Camera access is unavailable. Allow camera access in your browser settings and try again.';});}
async function openManualPairing(){const link=$('#pair-link-input')?.value?.trim(),pairing=parsePairingLink(link,location.origin);if(!pairing){toast('Paste a valid BEU Exam Dost pairing link.');return;}stopPairScanner();closeDialog();openPairApproval(pairing);}
async function showLinkedDevices(){const meta=syncClient.metadata();if(!meta?.credential){toast('Manage linked devices from your primary BEU Exam Dost app.');return;}syncClient.devices().then(devices=>{const rows=devices.map(device=>`<div class="sync-device-row"><span class="mini-icon green">${icon('check')}</span><span><b>${esc(device.label)}</b><small>${device.device_id===meta.deviceId?'This device':'Last active '+new Date(device.last_seen_at).toLocaleString('en-IN')}</small></span>${device.device_id===meta.deviceId?'<span class="badge green">This device</span>':btn('Revoke','sync-revoke','button outline small-button',`data-device="${esc(device.device_id)}"`)}</div>`).join('');contentDialog('Linked devices',`${rows||'<p>No linked devices found.</p>'}<p class="small muted">Revoking blocks future sync. An offline device clears its local link and encryption key when it reconnects. Data already copied elsewhere cannot be remotely erased.</p>`,btn('Close','cancel','button outline')+btn('Delete cloud sync data','sync-delete-account','button danger'));}).catch(error=>{if(error.status===401){clearRevokedDevice();toast('This device was revoked. Its sync link and encryption key were cleared.');return;}toast(error.message||'Could not load linked devices.');});}
function clearRevokedDevice(){syncClient.unlinkThisDevice();syncClient.cancelPairing();state=blank();clearCachedProfile();save();syncStatus='revoked';location.replace('/');}
async function logoutProfile(){const mobile=['Android','iOS'].includes(getDeviceInfo().os);try{if(mobile&&syncClient.metadata()?.credential)await syncClient.deleteAccount();else if(!mobile)await syncClient.logoutDevice();clearTimeout(syncTimeout);syncTimeout=null;syncBusy=false;syncClient.cancelPhonePairing();state=blank();localStorage.removeItem(KEY);clearCachedProfile();location.replace('/');}catch(error){toast(mobile?'Could not erase the synced profile. Your data is unchanged; reconnect and try again.':error.message||'Could not log out of this desktop.');}}
function confirmProfileLogout(){const mobile=['Android','iOS'].includes(getDeviceInfo().os);dialog(mobile?'Log out and erase your profile?':'Log out of this desktop?',mobile?'This permanently clears this device’s profile and study data, deletes the encrypted cloud copy, and removes access for linked desktops when they reconnect. This cannot be undone.':'Only this desktop’s saved profile and study data will be cleared. Your primary mobile profile and cloud data will remain available for pairing again.',btn('Cancel','cancel','button outline')+btn(mobile?'Erase profile and log out':'Log out','profile-logout-confirm','button danger'));}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='profile-logout')confirmProfileLogout();else if(action==='profile-logout-confirm'){closeDialog();logoutProfile();}});
