function confirmDeleteCloud(){dialog('Delete cloud sync data?','This deletes the shared cloud copy and unlinks every device. Your current device’s local data stays on this device.',btn('Keep cloud data','cancel','button outline')+btn('Delete cloud data','sync-delete-account-confirm','button danger'));}
async function deleteCloudSync(){try{await syncClient.deleteAccount();syncStatus='offline';closeDialog();render();toast('Cloud sync data deleted. This device’s local study data remains.');}catch(error){toast(error.message||'Could not delete cloud sync data.');}}
async function handleIncomingPairRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');if(parts[0]!=='link-device'||parts.length!==4)return;const raw=`${location.origin}/#/${parts.join('/')}`,pairing=parsePairingLink(raw,location.origin);if(!pairing)return;const key=`${pairing.sessionId}/${pairing.requestCredential}`;if(key===handledPairing)return;handledPairing=key;incomingPairing=pairing;if(!syncClient.metadata()?.credential){contentDialog('Link your trusted device first','Enable encrypted sync in BEU Exam Dost on your primary device before approving another device. The cloud stores encrypted data only.',btn('Cancel','cancel','button outline')+btn('Enable sync','sync-enable','button primary'));return;}openPairApproval(pairing);}
