const baseSetupPage=setup;setup=function(edit=false){const html=baseSetupPage(edit);return edit||state.profile?html:html.replace('<button class="primary full">','<p class="muted small telemetry-disclosure">Your name, college and branch are shared with BEU Exam Dost support via Telegram when your profile is created.</p><button class="primary full">');};const baseCreateAccountPage=createAccountPage;createAccountPage=function(){return baseCreateAccountPage().replace('<button class="onboarding-cta" type="submit">','<p class="muted small telemetry-disclosure">Your name, college and branch are shared with BEU Exam Dost support via Telegram when your profile is created.</p><button class="onboarding-cta" type="submit">');};const basePrivacyPage=privacy;privacy=function(){return basePrivacyPage().replace('Sync is off by default. If you enable it, your profile and study data listed above are sent over a secure connection and stored in the BEU Exam Dost cloud database so devices you approve can share it. The account is anonymous and does not require an email address, phone number, password, or OTP.','When enabled on your devices, study data is encrypted on your device before being stored in the BEU Exam Dost cloud database, then shared only with devices you approve.').replace('</article>','<div class="legal-alert"><p><strong>Support and usage notifications</strong></p><p>Profile creation sends your name, college and branch to BEU Exam Dost support through Telegram. App-open events send your device type only. Help & Requests submissions send the form details to the same support channel. Do not include sensitive information in support messages.</p></div></article>');};
