document.addEventListener('input',e=>{const input=e.target.closest('[data-pin-digit]');if(!input)return;const inputs=[...document.querySelectorAll('[data-pin-digit]')],index=inputs.indexOf(input),digits=input.value.replace(/\D/g,'');input.value=digits.slice(0,1);if(digits.length>1){digits.slice(1).split('').forEach((digit,offset)=>{if(inputs[index+offset+1])inputs[index+offset+1].value=digit;});const last=Math.min(inputs.length-1,index+digits.length-1);inputs[last]?.focus();return;}if(input.value)inputs[index+1]?.focus();});
